Object.assign(window.TEM8_DICTIONARY, {"sweeping":{"media":{"uk":"media/uk/sweeping__gb_1.mp3","us":"media/us/sweeping__us_1.mp3"},"oxford":{"phon":"ˈswiːpɪŋ","pos":"adjective","senses":[{"en":"having an important effect on a large part of something","cn":"影响广泛的；大范围的；根本性的","g":"[usually before noun]","ex":{"en":"sweeping reforms/changes","cn":"全面改革；彻底变化"}},{"en":"too general and failing to think about or understand particular examples","cn":"（过分）笼统的；一概而论的","g":"[usually before noun]","lab":"disapproving","ex":{"en":"a sweeping generalization/statement","cn":"笼统的概括；一概而论的说法"}},{"en":"a victory by a large number of votes, etc.","cn":"（在投票等中的）大胜，全胜"},{"en":"forming a curved shape","cn":"弧线的；弯曲的","g":"[only before noun]","ex":{"en":"a sweeping gesture (= with your hand or arm)","cn":"挥动的动作"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(弯曲)大幅度的,延伸的","en":"A sweeping curve is a long wide curve.","ex":{"en":"...the long sweeping curve of Rio's Guanabara Bay.","cn":"里约热内卢瓜纳巴拉湾蜿蜒绵长的海岸线"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(陈述、总结)一概而论的，笼统的","en":"If someone makes a sweeping statement or generalization, they make a statement which applies to all things of a particular kind, although they have not considered all the relevant facts carefully.","ex":{"en":"It is far too early to make sweeping statements about gene therapy.","cn":"现在对基因疗法下结论还为时过早。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(变化)巨大的，重要的，有广泛影响的,深远的","en":"Sweeping changes are large and very important or significant.","ex":{"en":"The new government has started to make sweeping changes in the economy","cn":"新政府已经着手在经济领域进行意义深远的改革。"}}]},"examples":[{"en":"Security forces were given sweeping powers to search homes.","cn":"安全部队获授予入户搜查的绝对权力。"},{"en":"a sweeping gesture (= with your hand or arm)","cn":"挥动的动作"}]},"swinging":{"media":{"uk":"media/uk/swinging__gb_1.mp3","us":"media/us/swinging__us_1.mp3"},"oxford":{"phon":"ˈswɪŋɪŋ","pos":"adjective","senses":[{"en":"lively and fashionable","cn":"活跃而时髦的","ex":{"en":"swinging singles","cn":"活跃时髦的单身族"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"活跃的;活泼的;时髦的;新潮的","en":"If you describe something or someone as swinging, you mean that they are lively and fashionable.","ex":{"en":"The stuffy '50s gave way to the swinging '60s.","cn":"古板乏味的 50 年代被多姿多彩的60年代所取代。"}}]},"examples":[{"en":"a swinging social life","cn":"令人兴奋的社交生活"}]},"swallowed":{"oxford":{"phon":"ˈswɒləʊ","pos":"verb","senses":[{"en":"to make food, drink, etc. go down your throat into your stomach","cn":"吞下；咽下"},{"en":"to move the muscles of your throat as if you were swallowing sth, especially because you are nervous （","cn":"由于紧张等）做吞咽动作"}]},"media":{"uk":"media/uk/swallow__gb_1.mp3","us":"media/us/swallow__us_1.mp3"}},"swear":{"oxford":{"phon":"sweə(r)","pos":"verb","senses":[{"en":"to use rude or offensive language, usually because you are angry","cn":"咒骂；诅咒；说脏话","g":"[intransitive]","ex":{"en":"She fell over and swore loudly.","cn":"她摔倒了，大骂了一声。"}},{"en":"to make a serious promise to do something","cn":"郑重承诺；发誓要；表示决心要","g":"[transitive, no passive]","ex":{"en":"He swore revenge on the man who had killed his father.","cn":"他发誓要向那个杀死他父亲的人报仇。"}},{"en":"to promise that you are telling the truth","cn":"赌咒发誓地说；肯定地说","g":"[transitive]","ex":{"en":"She swore (that) she’d never seen him before.","cn":"她明确表示自己以前从未见过他。"}},{"en":"to make a public or official promise, especially in court","cn":"（尤指在法庭上）发誓，郑重承诺","g":"[intransitive, transitive]","ex":{"en":"Witnesses were required to swear on the Bible.","cn":"证人须手按《圣经》宣誓。"}},{"en":"to make somebody promise not to tell something to anyone","cn":"使起誓（保密）","g":"[transitive]","ex":{"en":"Everyone was sworn to secrecy about what had happened.","cn":"关于已发生的事，每个人都依照要求起誓不外传。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"咒骂;诅咒;说脏话","en":"If someone swears, they use language that is considered to be rude or offensive, usually because they are angry.","ex":{"en":"It's wrong to swear and shout","cn":"破口大骂是不对的。"}},{"pos":"VERB 动词","cn":"发誓要;郑重承诺","en":"If you swear to do something, you promise in a serious way that you will do it.","ex":{"en":"Alan swore that he would do everything in his power to help us","cn":"艾伦许诺要尽其所能帮助我们。"}},{"pos":"VERB 动词","cn":"发誓，郑重声明，保证(所说属实)","en":"If you say that you swear that something is true or that you can swear to it, you are saying very firmly that it is true.","ex":{"en":"I swear I've told you all I know","cn":"我发誓我已经把我所知道的全都告诉你了。"}},{"pos":"VERB 动词","cn":"使发誓，使承诺(保守秘密)","en":"If someone is sworn to secrecy or is sworn to silence, they promise another person that they will not reveal a secret.","ex":{"en":"She was bursting to announce the news but was sworn to secrecy.","cn":"她急不可待想宣布这个消息，但却发过誓要守口如瓶。"}},{"pos":"","cn":"","en":"相关词组：swear by swear in"}]},"media":{"uk":"media/uk/swear__gb_1.mp3","us":"media/us/swear__us_1.mp3"},"examples":[{"en":"Everyone was sworn to secrecy about what had happened.","cn":"关于已发生的事，每个人都依照要求起誓不外传。"},{"en":"I think I put the keys back in the drawer, but I couldn't swear to it (= I'm not completely sure).","cn":"我想我把钥匙放回抽屉里了，不过我不敢肯定。"}]},"swim":{"oxford":{"phon":"swɪm","pos":"verb","senses":[{"en":"to move through water by moving your arms and legs, without touching the bottom","cn":"游泳；游水","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"I can't swim.","cn":"我不会游泳。"}},{"en":"to spend time swimming for pleasure","cn":"游泳（作为娱乐）","g":"[intransitive]","ex":{"en":"I go swimming twice a week.","cn":"我每星期游泳两次。"}},{"en":"to move through or across water","cn":"游；游动","g":"[intransitive]","ex":{"en":"Sharks must swim or die.","cn":"鲨鱼必须不停游动，否则就会死亡。"}},{"en":"to be covered with a lot of liquid","cn":"浸；泡；洒满；充溢着","g":"[intransitive]","ex":{"en":"The main course was swimming in oil.","cn":"主菜油汪汪的。"}},{"en":"to seem to be moving around, especially when you are ill or drunk","cn":"仿佛在旋转，似在晃动（尤指生病或酒醉时的感觉）","g":"[intransitive]","ex":{"en":"The pages swam before her eyes.","cn":"书页仿佛在她眼前晃动。"}},{"en":"to feel confused and/or as if everything is turning round and round","cn":"眩晕；感觉天旋地转","g":"[intransitive]","ex":{"en":"His head swam and he swayed dizzily.","cn":"他感觉天旋地转，摇晃起来。"}},{"en":"a period of time during which you swim","cn":"游泳","g":"[singular]","ex":{"en":"Let's go for a swim.","cn":"我们去游泳吧。"},"pos":"noun"},{"en":"(in compounds) related to or used for swimming","cn":"（构成复合词）与游泳有关的，游泳时用的","lab":"especially North American English","ex":{"en":"a swim meet (= a swimming competition between teams)","cn":"游泳比赛"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"游泳;游水","en":"When you swim, you move through water by making movements with your arms and legs.","ex":{"en":"She learned to swim when she was really tiny","cn":"她很小的时候就学会了游泳。"}},{"pos":"VERB 动词","cn":"参加游泳比赛","en":"If you swim a race, you take part in a swimming race.","ex":{"en":"She swam the 400 metres medley ten seconds slower than she did in 1980.","cn":"她 400 米混合泳的成绩比其 1980 年慢了 10 秒。"}},{"pos":"VERB 动词","cn":"游过(一段水域);横渡","en":"If you swim a stretch of water, you keep swimming until you have crossed it.","ex":{"en":"In 1875, Captain Matthew Webb became the first man to swim the English Channel.","cn":"1875年，马修·韦布船长成为横渡英吉利海峡的第一人。"}},{"pos":"VERB 动词","cn":"(鱼)游，游动","en":"When a fish swims, it moves through water by moving its body.","ex":{"en":"The barriers are lethal to fish trying to swim upstream.","cn":"这些障碍物对于想要往上游游动的鱼儿来说是致命的。"}},{"pos":"VERB 动词","cn":"(通常指生病时觉得物体仿佛在)旋转，摇晃","en":"If objects swim, they seem to be moving backwards and forwards, usually because you are ill.","ex":{"en":"Alexis suddenly could take no more: he felt too hot, he couldn't breathe, the room swam.","cn":"亚历克西斯突然觉得受不了了，他感到闷热，喘不上气，仿佛整间屋子在旋转。"}},{"pos":"VERB 动词","cn":"头晕;眩晕","en":"If your head is swimming, you feel unsteady and slightly ill.","ex":{"en":"The musty aroma of incense made her head swim.","cn":"熏香发霉的气味令她感到头晕。"}},{"pos":"VERB 动词","cn":"浸;泡;充溢着","en":"If something is swimming in liquid or is swimming with liquid, it is surrounded by and covered with it.","ex":{"en":"He polished off a large steak, salad, broccoli swimming in thick sauce, and half a litre of wine.","cn":"他狼吞虎咽地吃下了一大块牛排、很多色拉和浸着浓稠酱汁的花耶菜，还喝了半升红酒。"}},{"pos":"","cn":"","en":"sink or swim→see: ;"}]},"media":{"uk":"media/uk/swim__gb_1.mp3","us":"media/us/swim__us_1.mp3"},"examples":[{"en":"They spent the day swimming and sunbathing.","cn":"他们整整一天都在游泳和晒太阳。"},{"en":"How long will it take her to swim the Channel?","cn":"她游过英吉利海峡得用多长时间？"}]},"sword":{"media":{"img":["media/ldoce/img/sword.jpg","media/pic/sword_comp.jpg"],"uk":"media/uk/sword__gb_1.mp3","us":"media/us/sword__us_1.mp3"},"oxford":{"phon":"sɔːd","pos":"noun","senses":[{"en":"a weapon with a long metal blade (= sharp cutting part) and a handle","cn":"剑；刀","ex":{"en":"to draw/sheathe a sword (= to take it out of/put it into its cover)","cn":"拔剑；把剑插入鞘"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"剑;刀","en":"A sword is a weapon with a handle and a long sharp blade."},{"pos":"PHR-RECIP 相互短语","cn":"与…交锋;与…争论","en":"If you cross swords with someone, you disagree with them and argue with them about something.","ex":{"en":"...a candidate who's crossed swords with Labor by supporting the free-trade pact","cn":"因为支持自由贸易协定而与工党交锋的候选人"}},{"pos":"PHRASE 短语","cn":"(指兼有正面和负面影响的)双刃剑","en":"If you say that something is a double-edged sword or a two-edged sword, you mean that it has negative effects as well as positive effects."},{"pos":"","cn":"","en":"Sword of Damocles→see: ;"}]},"examples":[{"en":"to draw/sheathe a sword (= to take it out/put it into its cover)","cn":"拔剑；把剑插入鞘"},{"en":"The treaty hung like a sword of Damocles over French politics.","cn":"这个条约好像一把达摩克利斯之剑悬在法国政坛之上。"}]},"swipe":{"oxford":{"phon":"swaɪp","pos":"verb","senses":[{"en":"to hit or try to hit somebody/something with your hand or an object by moving your arm with a wide, curved movement","cn":"挥拳打；扬起巴掌打；挥起（物体）击打","g":"[intransitive, transitive]","ex":{"en":"He swiped at the ball and missed.","cn":"他挥棒击球但没击中。"}},{"en":"to steal something","cn":"偷；偷走","g":"[transitive]","lab":"informal","ex":{"en":"They’re always swiping other kids’ sweets.","cn":"他们总是偷吃其他孩子的糖果。"}},{"en":"to pass a plastic card, such as a credit card, through a special machine that is able to read the information that is stored on it","cn":"刷（磁卡）","g":"[transitive]","ex":{"en":"The cash register only opens once the card has been swiped.","cn":"收银机只有在刷卡后才会打开。"}},{"en":"to move your finger quickly across the screen of an electronic device such as a mobile phone or small computer in order to move text, pictures, etc. or give commands","cn":"（用手指在手机等电子设备屏幕上）快速滑动，输入手势指令","g":"[intransitive, transitive]","ex":{"en":"Switch on the phone and swipe your finger across the screen to unlock it.","cn":"打开手机，在屏幕上滑动手指来解锁。"}},{"en":"an act of hitting or trying to hit somebody/something by moving your arm or something that you are holding with a wide, curved movement","cn":"抡打；挥击","ex":{"en":"She took a swipe at him with her umbrella.","cn":"她抡起雨伞朝他打去。"},"pos":"noun"},{"en":"an act of criticizing somebody/something","cn":"批评；抨击","ex":{"en":"He used the interview to take a swipe at his critics.","cn":"他利用这次采访对批评他的人予以回击。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"挥起（棍棒等）击打","en":"If you swipe at a person or thing, you try to hit them with a stick or other object, making a swinging movement with your arm.","ex":{"en":"She swiped at Rusty as though he was a fly","cn":"她打拉斯蒂就像在打一只苍蝇。"}},{"pos":"VERB 动词","cn":"偷窃","en":"If you swipe something, you steal it quickly.","ex":{"en":"Five soldiers were each fined £140 for swiping a wheelchair from a disabled tourist","cn":"5 名士兵因偷窃一名残疾人游客的轮椅而每人被罚款 140 英镑。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指间接的)批评,抨击","en":"If you take a swipe at a person or an organization, you criticize them, usually in an indirect way.","ex":{"en":"Genesis recorded a song which took a swipe at greedy property developers who bought up and demolished people's homes","cn":"吉妮西丝录制了一首歌来抨击那些买下并毁坏人们家园的贪婪的房地产开发商。"}},{"pos":"VERB 动词","cn":"刷(信用卡等)","en":"If you swipe a credit card or swipe card through a machine, you pass it through a narrow space in the machine so that the machine can read information on the card's magnetic strip.","ex":{"en":"Swipe your card through the phone, then dial.","cn":"在电话机上刷卡，然后拨号。"}}]},"media":{"uk":"media/uk/swipe__gb_1.mp3","us":"media/us/swipe__us_1.mp3","img":["media/ldoce/img/ldoce_326.png"]},"examples":[{"en":"He used the interview to take a swipe at his critics.","cn":"他利用这次采访对批评他的人予以回击。"},{"en":"He swiped at the ball and missed.","cn":"他挥棒击球但没击中。"}]},"sweatshirt":{"media":{"uk":"media/uk/sweatshirt__gb_1.mp3","us":"media/us/sweatshirt__us_1.mp3"},"oxford":{"phon":"ˈswetʃɜːt","pos":"noun","senses":[{"en":"a piece of clothing for the upper part of the body, with long sleeves, usually made of thick cotton and often worn for sports","cn":"（长袖）运动衫"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长袖运动衫","en":"A sweatshirt is a loose warm piece of casual clothing, usually made of thick stretchy cotton, which covers the upper part of your body and your arms."}]}},"swell":{"media":{"uk":"media/uk/swell__gb_1.mp3","us":"media/us/swell__us_1.mp3"},"oxford":{"phon":"swel","pos":"verb","senses":[{"en":"to become bigger or rounder","cn":"膨胀；肿胀","g":"[intransitive]","ex":{"en":"Her arm was beginning to swell up where the bee had stung her.","cn":"她胳膊给蜜蜂蜇了，肿了起来。"}},{"en":"to go out or make something go out in a curved shape","cn":"（使）凸出，鼓出","g":"[intransitive, transitive]","ex":{"en":"The sails swelled (out) in the wind.","cn":"船帆鼓满了风。"}},{"en":"to increase or make something increase in number or size","cn":"（使）增加，增大，扩大","g":"[transitive, intransitive]","ex":{"en":"Last year's profits were swelled by a fall in production costs.","cn":"去年因生产成本下降，利润有所增加。"}},{"en":"to become louder","cn":"变得更响亮；增强","g":"[intransitive]","ex":{"en":"The cheering swelled through the hall.","cn":"欢呼声越来越大，响彻大厅。"}},{"en":"to be filled with a strong emotion","cn":"充满（激情）","g":"[countable]","ex":{"en":"to swell with pride","cn":"满腔自豪"}},{"en":"the movement of the sea when it rises and falls without the waves breaking","cn":"海浪的涌动；涌浪","g":"[countable, usually singular]","ex":{"en":"The boat was caught in a heavy (= strong) swell.","cn":"船遇上了大涌浪。"},"pos":"noun"},{"en":"the curved shape of something, especially a part of the body","cn":"（尤指身体部位）凸起的形状，鼓出处，隆起处","g":"[singular]","lab":"formal","ex":{"en":"the firm swell of her breasts","cn":"她挺拔的乳峰"},"pos":"noun"},{"en":"a situation in which something increases in size, number, strength, etc.","cn":"增加；增大；扩大；增强","g":"[singular]","ex":{"en":"a growing swell of support","cn":"越来越多的支持"},"pos":"noun"},{"en":"a slow steady increase in the volume of something","cn":"逐渐增强","g":"[singular]","pos":"noun"},{"en":"an important or fashionable person","cn":"重要人士；时髦人物","lab":"old-fashioned, informal，，","pos":"noun"},{"en":"very good, a lot of fun, etc.","cn":"很棒的；非常有趣的","ex":{"en":"We had a swell time.","cn":"我们过得开心极了。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)膨胀;(使)扩大;(使)增加","en":"If the amount or size of something swells or if something swells it, it becomes larger than it was before.","ex":{"en":"The human population swelled, at least temporarily, as migrants moved south","cn":"随着移居者南移,人口出现膨胀，至少是暂时性膨胀。"}},{"pos":"VERB 动词","cn":"(身体部位)肿胀，膨胀","en":"If something such as a part of your body swells, it becomes larger and rounder than normal.","ex":{"en":"Do your ankles swell at night?","cn":"你夜里脚踝肿吗？"}},{"pos":"VERB 动词","cn":"涌起，充满(某种情感)","en":"If you swell with a feeling, you are suddenly full of that feeling.","ex":{"en":"She could see her two sons swell with pride.","cn":"她能看出她的两个儿子充满了骄傲。"}},{"pos":"VERB 动词","cn":"(声音)增强,变响亮","en":"If sounds swell, they get louder.","ex":{"en":"Heavenly music swelled from nowhere.","cn":"不知从何处响起天籁般的音乐。"}},{"pos":"N-COUNT 可数名词","cn":"浪潮;浪涌","en":"A swell is the regular movement of waves up and down in the open sea.","ex":{"en":"We bobbed gently up and down on the swell of the incoming tide.","cn":"我们随着涨潮的浪涌轻轻地起伏。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极好的;了不起的;非常棒的","en":"You can describe something as swell if you think it is really nice.","ex":{"en":"I've had a swell time.","cn":"我过得极为开心。"}},{"pos":"","cn":"","en":"相关词组：swell up"}]},"examples":[{"en":"We are looking for more volunteers to swell the ranks (= increase the number) of those already helping.","cn":"我们期盼有更多的志愿者加入，以壮大目前已在提供帮助的队伍。"},{"en":"Last year's profits were swelled by a fall in production costs.","cn":"去年因生产成本下降，利润有所增加。"}]},"switchboard":{"oxford":{"phon":"ˈswɪtʃbɔːd","pos":"noun","senses":[{"en":"the central part of a phone system used by a company, etc., where phone calls are answered and put through (= connected) to the appropriate person or department; the people who work this equipment","cn":"（电话的）交换机，交换台，总机","ex":{"en":"a switchboard operator","cn":"交换台接线员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电话的)交换台，总台,总机","en":"A switchboard is a place in a large office or business where all the telephone calls are connected.","ex":{"en":"He asked to be connected to the central switchboard at London University","cn":"他要求转接到伦敦大学的电话总机。"}}]},"media":{"uk":"media/uk/switchboard__gb_1.mp3","us":"media/us/switchboard__us_1.mp3"},"examples":[{"en":"Hundreds of fans jammed the switchboard for over an hour.","cn":"在一个多小时里，好几百个崇拜者打去电话，交换台应接不暇。"},{"en":"Call the switchboard and ask for extension 410.","cn":"你先打电话到总机，然后要求转分机 410。"}]},"sweater":{"media":{"img":["media/pic/sweaters_jumpers_comp.jpg","media/thumb/crewneck.jpg"],"uk":"media/uk/sweater__gb_1.mp3","us":"media/us/sweater__us_1.mp3"},"oxford":{"phon":"ˈswetə(r)","pos":"noun","senses":[{"en":"a piece of clothing for the upper part of the body, made of wool or cotton, with long sleeves","cn":"套头衫；套头毛衣","ex":{"en":"She wore jeans and a sweater.","cn":"她穿着牛仔裤和套头毛衣。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"毛衣;针织衫","en":"A sweater is a warm knitted piece of clothing which covers the upper part of your body and your arms."}]}},"sweet":{"oxford":{"phon":"swiːt","pos":"adjective","senses":[{"en":"containing, or tasting as if it contains, a lot of sugar","cn":"含糖的；甜的","sc":"food/drink","ex":{"en":"a cup of hot sweet tea","cn":"一杯加糖热茶"}},{"en":"having a pleasant smell","cn":"香的；芳香的；芬芳的","sc":"smell","ex":{"en":"a sweet-smelling rose","cn":"芬芳的玫瑰"}},{"en":"having a pleasant sound","cn":"悦耳的；好听的","sc":"sound","ex":{"en":"a sweet voice","cn":"甜润的嗓音"}},{"en":"pleasant and not containing any harmful substances","cn":"纯净的；清新的；新鲜的","sc":"pure","ex":{"en":"the sweet air of a mountain village","cn":"山村的清新空气"}},{"en":"making you feel happy and/or satisfied","cn":"令人愉快的；惬意的；舒畅的","sc":"satisfying","ex":{"en":"Goodnight. Sweet dreams.","cn":"晚安。祝你做个甜蜜的梦。"}},{"en":"attractive","cn":"惹人喜爱","lab":"especially British English","sc":"attractive","ex":{"en":"His sister's a sweet young thing.","cn":"他妹妹是个讨人喜欢的小家伙。"}},{"en":"having or showing a kind character","cn":"善良的；好心的；和蔼的；温柔的","sc":"kind","ex":{"en":"She gave him her sweetest smile.","cn":"她向他投以极温柔的一笑。"}},{"en":"used to show that you approve of something","cn":"（表示赞许）好啊，太棒了","lab":"especially North American English, informal，，","sc":"good","ex":{"en":"Free tickets? Sweet!","cn":"免费赠票？太棒了！"}},{"en":"a small piece of sweet food, usually made with sugar and/or chocolate and eaten between meals","cn":"糖果","g":"[countable]","lab":"British English","sc":"food","ex":{"en":"a packet of sweets","cn":"一袋糖果"},"pos":"noun"},{"en":"a sweet dish eaten at the end of a meal","cn":"（餐末的）甜食，甜点","g":"[countable, uncountable]","lab":"British English","sc":"food","ex":{"en":"I haven't made a sweet today.","cn":"我今天没做甜点。"},"pos":"noun"},{"en":"a way of addressing somebody that you like or love","cn":"（称呼亲爱的人）亲爱的，宝贝儿","g":"[uncountable]","lab":"old-fashioned","sc":"person","ex":{"en":"Don't you worry, my sweet.","cn":"你可别担心，宝贝儿。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"甜的;味甘的","en":"Sweet food and drink contains a lot of sugar.","ex":{"en":"...a mug of sweet tea","cn":"一大杯甜茶"}},{"pos":"N-COUNT 可数名词","cn":"糖果","en":"Sweets are small sweet things such as toffees, chocolates, and mints."},{"pos":"N-VAR 可变名词","cn":"(尤指在餐厅吃饭时饭后的)甜食，甜点","en":"A sweet is something sweet, such as fruit or a pudding, that you eat at the end of a meal, especially in a restaurant.","ex":{"en":"The sweet was a mousse flavoured with whisky.","cn":"甜点是威士忌口味的慕斯。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"芬芳的;芳香的","en":"A sweet smell is a pleasant one, for example the smell of a flower.","ex":{"en":"...the sweet smell of her shampoo","cn":"她的洗发水的芳香"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(空气等)新鲜的,清新的;(水)纯净的,清澈的","en":"If you describe something such as air or water as sweet, you mean that it smells or tastes pleasantly fresh and clean.","ex":{"en":"I gulped a breath of sweet air.","cn":"我吸了一大口清新的空气。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)轻柔的,甜美的，悦耳的","en":"A sweet sound is pleasant, smooth, and gentle.","ex":{"en":"Her voice was as soft and sweet as a young girl's.","cn":"她的声音如少女般柔美悦耳。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人满意的;快意的","en":"If you describe something as sweet, you mean that it gives you great pleasure and satisfaction.","ex":{"en":"There are few things quite as sweet as revenge.","cn":"几乎没有比复仇更爽的事情了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"温和的;善良的;温柔的;可亲的","en":"If you describe someone as sweet, you mean that they are pleasant, kind, and gentle towards other people.","ex":{"en":"He was a sweet man but when he drank he tended to quarrel","cn":"他平时是一个温和的人，但喝了酒后往往就会又吵又闹。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(小孩，小东西)迷人的，漂亮的，可爱的","en":"If you describe a small person or thing as sweet, you mean that they are attractive in a simple or unsophisticated way.","ex":{"en":"...a sweet little baby girl","cn":"漂亮的小女孩"}},{"pos":"N-VOC 称呼名词","cn":"亲爱的,宝贝儿(用作爱称)","en":"You can address someone as sweet or my sweet if you are very fond of them.","ex":{"en":"I am so proud of you, my sweet!","cn":"我真为你骄傲，亲爱的！"}},{"pos":"PHRASE 短语","cn":"讨好;哄;巴结","en":"If you keep someone sweet, you do something to please them in order to prevent them from becoming annoyed or dissatisfied.","ex":{"en":"Where's the money to keep us sweet?","cn":"用来讨好我们的钱在哪呢？"}},{"pos":"","cn":"","en":"a sweet tooth→see: ;"}]},"media":{"uk":"media/uk/sweet__gb_1.mp3","us":"media/us/sweet__us_1.mp3","img":["media/ldoce/img/pile_sweets.jpg"]},"examples":[{"en":"He always does the work, but in his own sweet time.","cn":"工作他总是在做，但只在自己高兴的时候做。"},{"en":"We stayed in a sweet little hotel on the seafront.","cn":"我们住在海滨一家小巧玲珑的旅馆里。"}]},"sweets":{"oxford":{"phon":"swiːt","pos":"adjective","senses":[{"en":"containing, or tasting as if it contains, a lot of sugar","cn":"含糖的；甜的"},{"en":"having a pleasant smell","cn":"香的；芳香的；芬芳的"}]}},"sweat":{"media":{"uk":"media/uk/sweat__gb_1.mp3","us":"media/us/sweat__us_1.mp3"},"oxford":{"phon":"swet","pos":"noun","senses":[{"en":"drops of liquid that appear on the surface of your skin when you are hot, ill or afraid","cn":"汗","g":"[uncountable]","sc":"liquid on skin","ex":{"en":"beads of sweat","cn":"汗珠"}},{"en":"the state of being covered with sweat","cn":"出汗；流汗；一身汗","g":"[usually singular]","sc":"liquid on skin","ex":{"en":"I woke up in a sweat.","cn":"我醒来时浑身是汗。"}},{"en":"hard work or effort","cn":"繁重的工作；艰苦的劳动；累活儿；艰苦努力","g":"[uncountable]","lab":"informal","sc":"hard work","ex":{"en":"Growing your own vegetables sounds like a lot of sweat.","cn":"自己种菜吃，这恐怕很累吧。"}},{"en":"a sweatsuit or sweatpants","cn":"运动服；运动裤","g":"[plural]","lab":"informal, especially North American English，，","sc":"clothes","ex":{"en":"I hung around the house all day in my sweats.","cn":"我穿着运动服在家里晃荡了一整天。"}},{"en":"when you sweat, drops of liquid appear on the surface of your skin, for example when you are hot, ill or afraid","cn":"出汗；流汗","g":"[intransitive, transitive]","sc":"produce liquid on skin/surface","ex":{"en":"to sweat heavily","cn":"汗流浃背"},"pos":"verb"},{"en":"if something sweats, the liquid that is contained in it appears on its surface","cn":"（物体表面）渗出水分，结水珠","g":"[intransitive]","sc":"produce liquid on skin/surface","ex":{"en":"The cheese was beginning to sweat.","cn":"奶酪开始出水了。"},"pos":"verb"},{"en":"to work hard at something","cn":"艰苦努力；辛苦地干","g":"[intransitive]","sc":"work hard","ex":{"en":"Are you still sweating over that report?","cn":"你还在为那篇报道伤脑筋吗？"},"pos":"verb"},{"en":"to worry or feel nervous about something","cn":"担心；焦虑；不安","g":"[intransitive]","lab":"informal","sc":"worry","ex":{"en":"They really made me sweat during the interview.","cn":"面试过程中，他们的确使我忐忑不安。"},"pos":"verb"},{"en":"if you sweat meat or vegetables or let them sweat, you heat them slowly with a little fat in a pan that is covered with a lid","cn":"焖","g":"[transitive, intransitive]","lab":"British English","sc":"heat food","pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"汗;汗水;汗液","en":"Sweat is the salty colourless liquid which comes through your skin when you are hot, ill, or afraid.","ex":{"en":"Both horse and rider were dripping with sweat within five minutes","cn":"没过五分钟，马和骑手都大汗淋漓。"}},{"pos":"VERB 动词","cn":"出汗;流汗;发汗","en":"When you sweat, sweat comes through your skin.","ex":{"en":"Already they were sweating as the sun beat down upon them.","cn":"在阳光的强烈照射下他们已经汗流浃背。"}},{"pos":"N-COUNT 可数名词","cn":"满身大汗","en":"If someone is in a sweat, they are sweating a lot.","ex":{"en":"Every morning I would break out in a sweat","cn":"每天早上我都会出一身汗。"}},{"pos":"N-PLURAL 复数名词","cn":"同 sweatsuit 或 sweatpants","en":"Sweats are the same as a sweatsuit or sweatpants ."},{"pos":"PHRASE 短语","cn":"冒冷汗，出冷汗(指感到害怕或难堪)","en":"If someone is in a cold sweat or in a sweat, they feel frightened or embarrassed.","ex":{"en":"The very thought brought me out in a cold sweat.","cn":"一想到这我就一身冷汗。"}},{"pos":"PHRASE 短语","cn":"焦急地等待","en":"If someone sweats it out, they wait anxiously for a situation to improve or be resolved, because they cannot do anything about it.","ex":{"en":"The islanders can do little but sweat it out, wondering whether they will be forced to go and seek a new life elsewhere.","cn":"岛民不知道自己是否要被迫去往他处另谋生路，但却无能为力，只好干等。"}},{"pos":"CONVENTION 惯用语","cn":"没什么;小事一桩","en":"If a person says no sweat when you ask them about something or ask them to do something, they mean that it is not a problem or that it can be done quickly or easily.","ex":{"en":"'Many thanks.' — 'No sweat. Anything else?'","cn":"“非常感谢。”——“没什么，还需要别的吗？”"}},{"pos":"","cn":"","en":"blood, sweat, and tears→see: ; to sweat blood→see: ;"}]},"examples":[{"en":"‘Thanks for everything.’ ‘Hey, no sweat!’ “","cn":"谢谢你帮了这么多忙。” “嗐，没什么！”"},{"en":"She completed the routine without even working up a sweat.","cn":"她完成了一套常规动作，连一滴汗都没出。"}]},"swallowing":{"oxford":{"phon":"ˈswɒləʊ","pos":"verb","senses":[{"en":"to make food, drink, etc. go down your throat into your stomach","cn":"吞下；咽下"},{"en":"to move the muscles of your throat as if you were swallowing sth, especially because you are nervous （","cn":"由于紧张等）做吞咽动作"}]},"media":{"uk":"media/uk/swallow__gb_1.mp3","us":"media/us/swallow__us_1.mp3"}},"swan":{"media":{"uk":"media/uk/swan__gb_1.mp3","us":"media/us/swan__us_1.mp3"},"oxford":{"phon":"swɒn","pos":"noun","senses":[{"en":"a large bird that is usually white and has a long, thin neck. Swans live on or near water.","cn":"天鹅"},{"en":"to go around enjoying yourself in a way that annoys other people or makes them jealous","cn":"悠游；悠然闲逛","ex":{"en":"They've gone swanning off to Paris for the weekend.","cn":"他们周末到巴黎潇洒去了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"天鹅","en":"A swan is a large bird with a very long neck. Swans live on rivers and lakes and are usually white."},{"pos":"VERB 动词","cn":"逍遥自在;悠然自得","en":"If you describe someone as swanning around or swanning off, you mean that they go and have fun, rather than working or taking care of their responsibilities.","ex":{"en":"She spends her time swanning around the world","cn":"她一个人自由自在地环游世界。"}}]},"examples":[{"en":"They've gone swanning off to Paris for the weekend.","cn":"他们周末到巴黎潇洒去了。"},{"en":"He’s gone swanning off to Rome for the weekend!","cn":"他到罗马潇洒度周末去了！"}]},"sweetest":{"oxford":{"phon":"swiːt","pos":"adjective","senses":[{"en":"containing, or tasting as if it contains, a lot of sugar","cn":"含糖的；甜的"},{"en":"having a pleasant smell","cn":"香的；芳香的；芬芳的"}]}},"swap":{"media":{"uk":"media/uk/swap__gb_1.mp3","us":"media/us/swap__us_1.mp3"},"oxford":{"phon":"swɒp","pos":"verb","senses":[{"en":"to give something to somebody and receive something in exchange","cn":"交换（东西）","g":"[intransitive, transitive]","ex":{"en":"I've finished this magazine. Can I swap with you?","cn":"这本杂志我看完了，能跟你交换一下吗？"}},{"en":"to start doing somebody else’s job, etc. while they do yours","cn":"交换（工作）","g":"[intransitive]","ex":{"en":"I'll drive there and then we'll swap over on the way back.","cn":"去的时候我开车，回来的时候咱俩再倒换过来。"}},{"en":"to replace one person or thing with another","cn":"用…替换；把…换成；掉换","g":"[transitive]","lab":"especially British English","ex":{"en":"I think I'll swap this sweater for one in another colour.","cn":"我想把这件毛衣换成其他颜色的。"}},{"en":"an act of exchanging one thing or person for another","cn":"交换；掉换","g":"[usually singular]","ex":{"en":"Let's do a swap. You work Friday night and I'll do Saturday.","cn":"咱俩调个班吧。你星期五晚间上，我星期六上。"},"pos":"noun"},{"en":"a thing or person that has been exchanged for another","cn":"交换物；被掉换者","ex":{"en":"Most of my football stickers are swaps.","cn":"我的足球贴纸多数都是跟别人换来的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"交换","en":"If you swap something with someone, you give it to them and receive a different thing in exchange.","ex":{"en":"Next week they will swap places and will repeat the switch weekly","cn":"下周他们将交换座位，并且以后每周换一次。"}},{"pos":"VERB 动词","cn":"用…替换;把…换成;停下(手头的事)改做","en":"If you swap one thing for another, you remove the first thing and replace it with the second, or you stop doing the first thing and start doing the second.","ex":{"en":"Despite the heat, he'd swapped his overalls for a suit and tie","cn":"尽管很热，他还是脱掉工作服换上了西装和领带。"}},{"pos":"VERB 动词","cn":"交流，交换(意见);互相讲述(故事)","en":"If you swap stories or opinions with someone, you tell each other stories or give each other your opinions.","ex":{"en":"They all sat together at table, laughing and swapping stories.","cn":"他们都坐在桌子旁，有说有笑地讲述各自的故事。"}}]},"examples":[{"en":"I'll drive there and then we'll swap over on the way back.","cn":"去的时候我开车，回来的时候咱俩再倒换过来。"},{"en":"I'm going to swap you over. Mike will go first and Jon will go second.","cn":"我打算把你俩掉换一下。迈克先去，乔恩后去。"}]},"swollen":{"oxford":{"phon":"ˈswəʊlən","pos":"adjective","senses":[{"en":"larger than normal, especially as a result of a disease or an injury","cn":"肿胀的；肿起来的","ex":{"en":"swollen glands","cn":"肿胀的腺体"}},{"en":"containing more water than normal","cn":"涨水的；上涨的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(身体部位)肿胀的,肿起来的","en":"If a part of your body is swollen, it is larger and rounder than normal, usually as a result of injury or illness.","ex":{"en":"My eyes were so swollen I could hardly see.","cn":"我的眼睛肿得很厉害，几乎看不到东西。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(河水)上涨的,湍流的","en":"A swollen river has more water in it and flows faster than normal, usually because of heavy rain."},{"pos":"","cn":"","en":"Swollen is the past participle of swell."}]},"media":{"uk":"media/uk/swollen__gb_2.mp3","us":"media/us/swollen__us_2.mp3"},"examples":[{"en":"Her eyes were red and swollen from crying.","cn":"她哭得两眼又红又肿。"},{"en":"swollen glands","cn":"肿胀的腺体"}]},"swimsuit":{"media":{"uk":"media/uk/swimsuit__gb_1.mp3","us":"media/us/swimsuit__us_1.mp3"},"oxford":{"phon":"ˈswɪmsuːt","pos":"noun","senses":[{"en":"a piece of clothing worn for swimming, especially the type worn by women and girls","cn":"（尤指女式）游泳衣"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指女式)游泳衣","en":"A swimsuit is a piece of clothing that is worn for swimming, especially by women and girls."}]}},"swans":{"oxford":{"phon":"swɒn","pos":"noun","senses":[{"en":"a large bird that is usually white and has a long thin neck. Swans live on or near water.","cn":"天鹅"},{"en":"( BrE ) ( informal, disapproving ) to go around enjoying yourself in a way that annoys other people or makes them jealous","cn":"悠游；悠然闲逛"}]},"media":{"uk":"media/uk/swan__gb_1.mp3","us":"media/us/swan__us_1.mp3"}},"sw":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"short wave","cn":"短波","lab":"especially British English","ex":{"en":"SW and LW radio","cn":"短波及长波无线电设备"}},{"en":"south-west; south-western","cn":"西南方（的）；西南部（的）","ex":{"en":"SW Australia","cn":"澳大利亚西南部"}}]},"examples":[{"en":"SW and LW radio","cn":"短波及长波无线电设备"},{"en":"SW Australia","cn":"澳大利亚西南部"}],"collins":{"senses":[{"pos":"","cn":"","en":"SW is a written abbreviation for (书面缩略=) south-west .","ex":{"en":"...King's Road, London SW 3.","cn":"伦敦西南区 3 号，国王路"}}]}},"swept":{"collins":{"senses":[{"pos":"","cn":"","en":"Swept is the past tense and past participle of sweep."}]},"media":{"uk":"media/uk/swept__gb_1.mp3","us":"media/us/swept__us_1.mp3"}},"sweeter":{"oxford":{"phon":"swiːt","pos":"adjective","senses":[{"en":"containing, or tasting as if it contains, a lot of sugar","cn":"含糖的；甜的"},{"en":"having a pleasant smell","cn":"香的；芳香的；芬芳的"}]}},"swift":{"media":{"uk":"media/uk/swift__gb_1.mp3","us":"media/us/swift__us_1.mp3"},"oxford":{"phon":"swɪft","pos":"adjective","senses":[{"en":"happening or done quickly and immediately; doing something quickly","cn":"迅即发生的；马上做出的；迅速的","ex":{"en":"swift action","cn":"迅速的行动"}},{"en":"moving very quickly; able to move very quickly","cn":"速度快的；敏捷的；矫健的","ex":{"en":"a swift current","cn":"湍急的水流"}},{"en":"a small bird with long, narrow wings, similar to a swallow","cn":"雨燕","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快的;迅速的","en":"A swift event or process happens very quickly or without delay.","ex":{"en":"Our task is to challenge the UN to make a swift decision","cn":"我们的任务是敦促联合国快速做出决策。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快速移动的;速度非常快的","en":"Something that is swift moves very quickly.","ex":{"en":"With a swift movement, Matthew Jerrold sat upright.","cn":"马修· 杰罗尔德迅速坐直了。"}},{"pos":"N-COUNT 可数名词","cn":"雨燕","en":"A swift is a small bird with long curved wings."}]},"examples":[{"en":"The White House was swift to deny the rumours.","cn":"白宫立刻对这些传言予以否认。"},{"en":"She moved swiftly to the rescue.","cn":"她迅速赶来营救。"}]},"swings":{"oxford":{"phon":"swɪŋ","pos":"verb","senses":[{"en":"to move backwards or forwards or from side to side while hanging from a fixed point; to make sth do this （","cn":"使）摆动，摇摆，摇荡"},{"en":"to move from one place to another by holding sth that is fixed and pulling yourself along, up, etc.","cn":"纵身跃向；荡向；悬吊到"}]},"media":{"img":["media/pic/toys_comp.jpg","media/thumb/swing.jpg"],"uk":"media/uk/swing__gb_1.mp3","us":"media/us/swing__us_1.mp3"}},"swing":{"media":{"img":["media/ldoce/img/swing.jpg","media/pic/toys_comp.jpg"],"uk":"media/uk/swing__gb_1.mp3","us":"media/us/swing__us_1.mp3"},"oxford":{"phon":"swɪŋ","pos":"verb","senses":[{"en":"to move backwards or forwards or from side to side while hanging from a fixed point; to make something do this","cn":"（使）摆动，摇摆，摇荡","g":"[intransitive, transitive]","sc":"hang and move","ex":{"en":"His arms swung as he walked.","cn":"他边走边摆着双臂。"}},{"en":"to move from one place to another by holding something that is fixed and pulling yourself along, up, etc.","cn":"纵身跃向；荡向；悬吊到","g":"[intransitive, transitive]","sc":"hang and move","ex":{"en":"The gunshot sent monkeys swinging away through the trees.","cn":"枪声一响，猴子纷纷在树丛中飞跃荡走。"}},{"en":"to move or make something move with a wide curved movement","cn":"（使）弧线运动，转弯，转动","g":"[intransitive, transitive]","sc":"move in curve","ex":{"en":"A line of cars swung out of the palace gates.","cn":"一队汽车拐出了宫门。"}},{"en":"to change or make somebody/something change from one opinion, mood, etc. to another","cn":"（使）改变（意见、情绪等）","g":"[intransitive, transitive]","sc":"change opinion/mood","ex":{"en":"The state has swung from Republican to Democrat.","cn":"这个州原先支持共和党，现在倒向了民主党。"}},{"en":"to turn or change direction suddenly; to make something do this","cn":"（使）突然转向，突然转身","g":"[intransitive, transitive]","sc":"turn quickly","ex":{"en":"She swung back to face him.","cn":"她转身面对他。"}},{"en":"to try to hit somebody/something","cn":"（挥动某物）朝…打去","g":"[intransitive, transitive]","sc":"try to hit","ex":{"en":"She swung at me with the iron bar.","cn":"她挥着铁棍朝我打来。"}},{"en":"to succeed in getting or achieving something, sometimes in a slightly dishonest way","cn":"（有时略微不正当地）获得，搞到，办成","g":"[transitive]","lab":"informal","sc":"do/get something","ex":{"en":"We're trying to swing it so that we can travel on the same flight.","cn":"我们正在想法子，好坐上同一个航班。"}},{"en":"to have a strong rhythm","cn":"有强劲的节奏；节奏感强","g":"[intransitive]","sc":"of music"},{"en":"if a party, etc. is swinging, there are a lot of people there having a good time","cn":"热闹；令人开心","g":"[intransitive]","lab":"informal","sc":"of party"},{"en":"a swinging movement or rhythm","cn":"摆动；挥动；转动；强劲节奏","g":"[countable]","sc":"movement","ex":{"en":"He took a wild swing at the ball.","cn":"他对准球猛地挥拍一击。"},"pos":"noun"},{"en":"a change from one opinion or situation to another; the amount by which something changes","cn":"改变；改变的程度","g":"[countable]","sc":"of opinion/mood","ex":{"en":"Voting showed a 10 per cent swing to Labour.","cn":"投票显示 10% 的人转而支持工党。"},"pos":"noun"},{"en":"a seat for swinging on, hung from above on ropes or chains","cn":"秋千","g":"[countable]","sc":"hanging seat","ex":{"en":"The kids were playing on the swings.","cn":"孩子们在荡秋千。"},"pos":"noun"},{"en":"the swinging movement you make with your arms and body when you hit the ball in the game of golf","cn":"挥杆动作","g":"[singular]","sc":"in golf","ex":{"en":"I need to work on my swing.","cn":"我需要改进挥杆动作。"},"pos":"noun"},{"en":"a type of jazz with a smooth rhythm, played especially by big dance bands in the 1930s","cn":"摇摆乐（流行于 20 世纪 30 年代）","g":"[uncountable]","sc":"music","pos":"noun"},{"en":"a quick journey, especially one made by a politician, in which somebody visits several different places in a short time","cn":"（尤指从政者在多处逗留的）短期快速行程","g":"[singular]","lab":"North American English","sc":"journey","ex":{"en":"a three-day campaign swing through California","cn":"为期三天的加利福尼亚巡回竞选旅程"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)摆动;(使)摇摆;(使)摇荡","en":"If something swings or if you swing it, it moves repeatedly backwards and forwards or from side to side from a fixed point.","ex":{"en":"The sail of the little boat swung crazily from one side to the other","cn":"小船的帆猛烈地左右摇摆着。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)成弧线运动;(使)转动;(使)转弯","en":"If something swings in a particular direction or if you swing it in that direction, it moves in that direction with a smooth, curving movement.","ex":{"en":"The torchlight swung across the little beach and out over the water, searching","cn":"手电筒的光在小海滩上扫过，而后照向水面搜索着。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)急转弯;(使)突然转向","en":"If a vehicle swings in a particular direction, or if the driver swings it in a particular direction, they turn suddenly in that direction.","ex":{"en":"Joanna swung back on to the main approach and headed for the airport","cn":"乔安娜猛地调转车头回到主路上，朝机场开去。"}},{"pos":"VERB 动词","cn":"(通常指人因受惊)急转身","en":"If someone swings around, they turn around quickly, usually because they are surprised.","ex":{"en":"She swung around to him, spilling her tea without noticing it.","cn":"她一下子转身面向他，茶水溅了出来都没注意到。"}},{"pos":"VERB 动词","cn":"(挥动手臂等)朝…打去;朝…挥击;挥向","en":"If you swing at a person or thing, you try to hit them with your arm or with something that you are holding.","ex":{"en":"Blanche swung at her but she moved her head back and Blanche missed","cn":"布兰奇挥手朝她打去，但她头向后一闪，布兰奇没有打到。"}},{"pos":"N-COUNT 可数名词","cn":"秋千","en":"A swing is a seat hanging by two ropes or chains from a metal frame or from the branch of a tree. You can sit on the seat and move forwards and backwards through the air."},{"pos":"N-UNCOUNT 不可数名词","cn":"摇摆乐(流行于 20 世纪 30 年代的爵士舞曲)","en":"Swing is a style of jazz dance music that was popular in the 1930's. It was played by big bands."},{"pos":"N-COUNT 可数名词","cn":"(意见、态度或感情的)改变;(尤指)突变，巨变","en":"A swing in people's opinions, attitudes, or feelings is a change in them, especially a sudden or big change.","ex":{"en":"There was a massive twenty per cent swing away from the Conservatives to the Liberal Democrats","cn":"出现了一个巨大转变:多达20％的人由支持保守党转而支持自由民主党。"}},{"pos":"VERB 动词","cn":"(意见、态度或感情)改变;(尤指)突然转变，完全改变","en":"If people's opinions, attitudes, or feelings swing, they change, especially in a sudden or extreme way.","ex":{"en":"In two years' time there is a presidential election, and the voters could swing again","cn":"总统选举在两年后举行，届时选民们可能会再次倒向另一方。"}},{"pos":"N-COUNT 可数名词","cn":"(政治家等的)巡回,巡视,巡游","en":"If someone such as a politician makes a swing through a particular country or area, they go on a quick trip through it, visiting a number of different places.","ex":{"en":"...a campaign swing through South Dakota and Texas.","cn":"在南达科他州和得克萨斯州的巡回竞选活动"}},{"pos":"PHRASE 短语","cn":"在热烈进行中;处于兴盛阶段","en":"If something is in full swing, it is operating fully and is no longer in its early stages.","ex":{"en":"When we returned, the party was in full swing and the dance floor was crowded","cn":"我们回来时，聚会已进入高潮，舞池里挤满了人。"}},{"pos":"PHRASE 短语","cn":"融入;完全投入;对…乐在其中","en":"If you get into the swing of something, you become very involved in it and enjoy what you are doing.","ex":{"en":"Everyone understood how hard it was to get back into the swing of things after such a long absence.","cn":"每个人都知道这么长时间不在，再重新完全融入进来有多难。"}},{"pos":"PHRASE 短语","cn":"热闹有趣;气氛热烈","en":"If you say that something is going with a swing, you mean that it is lively and exciting.","ex":{"en":"Sara Lewis' impressive recipes are guaranteed to make the party go with a swing.","cn":"萨拉·刘易斯令人赞不绝口的食谱一定能使聚会的气氛热烈非凡。"}},{"pos":"PHRASE 短语","cn":"有得必有失","en":"If you say that a situation is swings and roundabouts, you mean that there are as many gains as there are losses."},{"pos":"","cn":"","en":"no room to swing a cat→see: ;"}]},"examples":[{"en":"I don't think there's anything wrong with her — she's just swinging the lead.","cn":"我认为她没有什么病，只不过是在装病偷懒而已。"},{"en":"The state has swung from Republican to Democrat.","cn":"这个州原先支持共和党，现在倒向了民主党。"}]},"sweep":{"media":{"uk":"media/uk/sweep__gb_1.mp3","us":"media/us/sweep__us_1.mp3"},"oxford":{"phon":"swiːp","pos":"verb","senses":[{"en":"to clean a room, surface, etc. using a broom (= a type of brush on a long handle)","cn":"扫；打扫；清扫","g":"[transitive, intransitive]","sc":"with brush or hand","ex":{"en":"to sweep the floor","cn":"清扫地板"}},{"en":"to remove something from a surface using a brush, your hand, etc.","cn":"扫去；清除","g":"[transitive]","sc":"with brush or hand","ex":{"en":"She swept the crumbs into the wastebasket.","cn":"她把面包屑扫进废纸篓里。"}},{"en":"to move or push somebody/something suddenly and with a lot of force","cn":"（迅猛地）推送，吹走，冲走，带走","g":"[transitive]","sc":"move quickly/with force","ex":{"en":"The little boat was swept out to sea.","cn":"小船被吹到大海里去了。"}},{"en":"to move suddenly and/or with force over an area or in a particular direction","cn":"猛烈吹过；掠过；席卷；横扫","g":"[intransitive, transitive]","sc":"move quickly/with force","ex":{"en":"Rain swept in through the broken windows.","cn":"雨水从破窗户灌进屋内。"}},{"en":"to move quickly and/or smoothly, especially in a way that impresses or is intended to impress other people","cn":"步态轻盈地走；大模大样地走","g":"[intransitive]","lab":"figurative","sc":"of a person","ex":{"en":"Without another word she swept out of the room.","cn":"她再没说话，大模大样地走出房间。"}},{"en":"to move something, especially your hand or arm, quickly and smoothly in a particular direction","cn":"挥动，舞动（尤指手或臂）","g":"[transitive]","sc":"of a person","ex":{"en":"He rushed to greet her, sweeping his arms wide.","cn":"他张开双臂舞动着，冲过去迎接她。"}},{"en":"to suddenly affect somebody strongly","cn":"突然袭来","g":"[intransitive]","sc":"of feelings","ex":{"en":"A wave of tiredness swept over her.","cn":"她感到浑身疲惫。"}},{"en":"to spread quickly","cn":"迅速传播","g":"[intransitive, transitive]","sc":"of ideas/fashions","ex":{"en":"Rumours of his resignation swept through the company.","cn":"他辞职的传言在全公司传播开了。"}},{"en":"to move over an area, especially in order to look for something","cn":"扫视；掠过；搜索","g":"[intransitive, transitive]","sc":"look/move over area","ex":{"en":"His eyes swept around the room.","cn":"他把房间扫视了一遍。"}},{"en":"to move, or move something, over a surface, touching it lightly","cn":"（使）轻轻掠过，轻轻擦过","g":"[transitive]","sc":"touch surface","ex":{"en":"Her dress swept the ground as she walked.","cn":"她行走时衣裙拖在地上。"}},{"en":"to brush, comb, etc. your hair in a particular direction","cn":"梳；刷；掠","g":"[transitive]","sc":"hair","ex":{"en":"Her hair was swept back from her face.","cn":"她的头发是从前边往后梳的。"}},{"en":"to form a long, smooth curve","cn":"蜿蜒；呈弧线延伸","g":"[intransitive]","sc":"of landscape","ex":{"en":"The hotel gardens sweep down to the beach.","cn":"旅馆的花园呈缓坡一直延伸到海滩。"}},{"en":"to win all the games in a series of games against another team or all the parts of a contest","cn":"（在系列比赛中）获得全部胜利，囊括各项冠军","g":"[transitive]","lab":"North American English","sc":"in sport","ex":{"en":"The Blue Jays have a chance to sweep the series.","cn":"蓝鸟队有机会横扫系列赛。"}},{"en":"an act of cleaning a room, surface, etc. using a broom","cn":"扫；打扫；清扫","g":"[countable, usually singular]","sc":"with brush","ex":{"en":"Give the room a good sweep.","cn":"把房间好好打扫一下。"},"pos":"noun"},{"en":"a smooth curving movement","cn":"挥动；掠","g":"[countable]","lab":"figurative","sc":"curving movement","ex":{"en":"He indicated the door with a sweep of his arm.","cn":"他一挥胳膊指向门。"},"pos":"noun"},{"en":"a long, often curved, piece of road, river, coast, etc.","cn":"（道路、河流、海岸等）一长段，绵延弯曲的地带，呈缓坡状的地带","g":"[countable, usually singular]","sc":"landscape","ex":{"en":"the broad sweep of white cliffs around the bay","cn":"环绕海湾的一段白色悬崖"},"pos":"noun"},{"en":"the range of an idea, a piece of writing, etc. that considers many different things","cn":"广泛性；广博的范围；广度","g":"[uncountable]","sc":"range","ex":{"en":"Her book covers the long sweep of the country's history.","cn":"她的著作涵盖了该国漫长的历史。"},"pos":"noun"},{"en":"a movement over an area, for example in order to search for something or attack something","cn":"巡行；搜索；扫荡","g":"[countable]","sc":"movement/search over area","ex":{"en":"The rescue helicopter made another sweep over the bay.","cn":"救援直升机在海湾上空又搜索了一遍。"},"pos":"noun"},{"en":"a person whose job is to clean the inside of chimneys","cn":"烟囱清扫工","g":"[countable]","sc":"chimney","pos":"noun"},{"en":"a sweepstake (= a type of betting in which the winner gets all the money bet by everyone else)","cn":"赌金全赢制","g":"[countable]","lab":"North American English also","sc":"gambling","pos":"noun"},{"en":"a series of games that a team wins against another team; the fact of winning all the parts of a contest","cn":"（两支球队对赛其中一方）全胜的一系列比赛；囊括冠军","g":"[countable]","lab":"North American English","sc":"in sport","ex":{"en":"a World Series sweep","cn":"在世界职业棒球系列赛中囊括冠军"},"pos":"noun"},{"en":"a time when television companies examine their programmes to find out which ones are the most popular, especially in order to calculate advertising rates","cn":"收视率调查（电视台为查明节目受欢迎度，尤为计算广告费）","g":"[plural]","lab":"North American English","sc":"television","ex":{"en":"the May ratings sweeps","cn":"5月收视率横扫"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"扫;掸;打扫;清扫","en":"If you sweep an area of floor or ground, you push dirt or rubbish off it using a brush with a long handle.","ex":{"en":"The owner of the store was sweeping his floor when I walked in","cn":"当我走进商店的时候，店主正在扫地。"}},{"pos":"VERB 动词","cn":"拂去;掸去","en":"If you sweep things off something, you push them off with a quick smooth movement of your arm.","ex":{"en":"I swept rainwater off the flat top of a gravestone","cn":"我拂去了墓碑顶上的雨水。"}},{"pos":"VERB 动词","cn":"梳,拢(头发)","en":"If someone with long hair sweeps their hair into a particular style, they put it into that style.","ex":{"en":"...stylish ways of sweeping your hair off your face","cn":"露出脸形的时髦发式"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(手臂)挥动","en":"If your arm or hand sweeps in a particular direction, or if you sweep it there, it moves quickly and smoothly in that direction.","ex":{"en":"His arm swept around the room","cn":"他伸出手臂绕着房间挥了一圈。"}},{"pos":"VERB 动词","cn":"(风、汹涌的海水等)席卷,横扫,掠过","en":"If wind, a stormy sea, or another strong force sweeps someone or something along, it moves them quickly along.","ex":{"en":"...landslides that buried homes and swept cars into the sea","cn":"埋没家园并把汽车卷入大海的山体滑坡"}},{"pos":"VERB 动词","cn":"将…迅速送到","en":"If you are swept somewhere, you are taken there very quickly.","ex":{"en":"The visitors were swept past various monuments","cn":"游客们被带着走马观花地参观了各种纪念碑。"}},{"pos":"VERB 动词","cn":"扫过;掠过;疾驰而过","en":"If something sweeps from one place to another, it moves there extremely quickly.","ex":{"en":"An icy wind swept through the streets","cn":"一阵寒风扫过街道。"}},{"pos":"VERB 动词","cn":"(事件、思想、信仰)迅速传播,席卷","en":"If events, ideas, or beliefs sweep through a place, they spread quickly through it.","ex":{"en":"A flu epidemic is sweeping through Moscow.","cn":"流感正在莫斯科迅速蔓延。"}},{"pos":"VERB 动词","cn":"(通常指生气时)大模大样地走,趾高气扬地走","en":"If someone sweeps into a place, they walk into it in a proud, confident way, often when they are angry.","ex":{"en":"She swept into the conference room","cn":"她大模大样地走入会议室。"}},{"pos":"VERB 动词","cn":"彻底删掉;迅速除去","en":"If a person or thing sweeps something away or aside, they remove it quickly and completely.","ex":{"en":"The commission's conclusions sweep away a decade of denials and cover-ups","cn":"委员会的结论将十年来的否认和掩饰无情地揭开。"}},{"pos":"VERB 动词","cn":"(目光)扫视;(灯光)扫过,掠过","en":"If lights or someone's eyes sweep an area, they move across the area from side to side.","ex":{"en":"Helicopters with searchlights swept the park which was sealed off","cn":"直升飞机的探照灯来回扫射这个被封锁的公园。"}},{"pos":"VERB 动词","cn":"蜿蜒,延伸;绵延","en":"If land or water sweeps somewhere, it stretches out in a long, wide, curved shape.","ex":{"en":"The land sweeps away from long areas of greenery.","cn":"这块地从草木茂盛的狭长地带一直伸展开来。"}},{"pos":"N-COUNT 可数名词","cn":"(道路、河流)绵延弯曲的地带,宽广而弯曲的一长段","en":"A sweep of land or water forms a long, wide, curved shape.","ex":{"en":"The ground fell away in a broad sweep down to the river.","cn":"转过一处大弯后，地面消失在与河水相接处。"}},{"pos":"VERB 动词","cn":"轻松赢得(竞选等)","en":"If a person or group sweeps an election or sweeps to victory, they win the election easily.","ex":{"en":"...a man who's promised to make radical changes to benefit the poor has swept the election","cn":"承诺彻底改善贫困人口状况的候选人轻松赢得了选举。"}},{"pos":"N-COUNT 可数名词","cn":"搜查;搜索;扫荡","en":"If someone makes a sweep of a place, they search it, usually because they are looking for people who are hiding or for an illegal activity.","ex":{"en":"Two of the soldiers swiftly began making a sweep of the premises","cn":"两名士兵立即开始搜索该建筑物。"}},{"pos":"N-SING 单数名词","cn":"广泛性;广度","en":"If you refer to the sweep of something, you are indicating that it includes a large number of different events, qualities, or opinions.","ex":{"en":"...the whole sweep of German social and political history.","cn":"德国社会政治的完整历史"}},{"pos":"PHRASE 短语","cn":"掩盖;掩饰","en":"If someone sweeps something bad or wrong under the carpet, or if they sweep it under the rug, they try to prevent people from hearing about it.","ex":{"en":"For a long time this problem has been swept under the carpet.","cn":"这一问题被掩盖了很长一段时间。"}},{"pos":"PHRASE 短语","cn":"在(比赛中)大获全胜;横扫","en":"If you make a clean sweep of something such as a series of games or tournaments, you win them all.","ex":{"en":"...the first club to make a clean sweep of all three trophies.","cn":"第一个将3项杯赛奖杯悉数收入囊中的俱乐部。"}},{"pos":"PHRASE 短语","cn":"使一见倾心;把…一下子迷住","en":"If someone sweeps you off your feet, you fall in love with them very quickly because you find them very attractive or exciting. to sweep the board→see: ;","ex":{"en":"I was swept off my feet. I had always dreamed of being an officer's wife.","cn":"我被迷得神魂颠倒，一直梦想着成为官太太。"}},{"pos":"","cn":"","en":"相关词组：sweep up"}]},"examples":[{"en":"New Jersey swept Detroit last season.","cn":"在上个赛季，新泽西队全胜底特律队。"},{"en":"The rescue helicopter made another sweep over the bay.","cn":"救援直升机在海湾上空又搜索了一遍。"}]},"swimming":{"media":{"img":["media/pic/swimming_comp.jpg","media/thumb/crawl.jpg"],"uk":"media/uk/swimming__gb_1.mp3","us":"media/us/swimming__us_1.mp3"},"oxford":{"phon":"ˈswɪmɪŋ","pos":"noun","senses":[{"en":"the sport or activity of swimming","cn":"游泳；游泳运动","ex":{"en":"Swimming is a good form of exercise.","cn":"游泳是很好的锻炼方式。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"游泳;游泳运动","en":"Swimming is the activity of swimming, especially as a sport or for pleasure.","ex":{"en":"Swimming is probably the best form of exercise you can get.","cn":"游泳或许是现有的最佳锻炼方式。"}}]},"examples":[{"en":"Swimming is a good form of exercise.","cn":"游泳是很好的锻炼方式。"},{"en":"Swimming is great exercise.","cn":"游泳是很好的锻炼。"}]},"swung":{"collins":{"senses":[{"pos":"","cn":"","en":"Swung is the past tense and past participle of swing."}]},"media":{"uk":"media/uk/swung__gb_1.mp3","us":"media/us/swung__us_1.mp3"}},"swiftly":{"oxford":{"phon":"ˈswɪftli","pos":"adverb","senses":[{"en":"quickly; after a very short time","cn":"迅速地 经过很短的时间","ex":{"en":"She moved swiftly to the rescue.","cn":"她迅速前去救援。"}}]},"media":{"uk":"media/uk/swiftly__gb_1.mp3","us":"media/us/swiftly__us_1.mp3"},"examples":[{"en":"She moved swiftly to the rescue.","cn":"她迅速赶来营救。"},{"en":"My letter received a swift reply.","cn":""}]},"switch":{"media":{"uk":"media/uk/switch__gb_1.mp3","us":"media/us/switch__us_1.mp3"},"oxford":{"phon":"swɪtʃ","pos":"verb","senses":[{"en":"to change or make something change from one thing to another","cn":"（使）改变，转变，突变","g":"[intransitive, transitive]","ex":{"en":"We're in the process of switching over to a new system of invoicing.","cn":"我们正在转用新的发票制度。"}},{"en":"to exchange one thing for another","cn":"交换；掉换；转换；对调","g":"[transitive]","ex":{"en":"The dates of the last two exams have been switched.","cn":"最后两门考试的日期掉换了。"}},{"en":"to do somebody else’s job for a short time or work during different hours so that they can do your job or work during your usual hours","cn":"调班；临时掉换工作时间","g":"[intransitive, transitive]","ex":{"en":"I can't work next weekend—will you switch with me?","cn":"下个周末我不能上班，咱俩调个班好不好？"}},{"en":"a small device that you press or move up and down in order to turn a light or piece of electrical equipment on and off","cn":"（电路的）开关，闸，转换器","lab":"figurative","ex":{"en":"a light switch","cn":"电灯开关"},"pos":"noun"},{"en":"a change from one thing to another, especially when this is sudden and complete","cn":"（尤指突然彻底的）改变，转变","ex":{"en":"a policy switch","cn":"政策的转变"},"pos":"noun"},{"en":"the points on a railway line","cn":"（铁路的）转辙器，道岔","lab":"North American English","pos":"noun"},{"en":"a thin stick that bends easily","cn":"（细软）枝条；鞭子","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(电路的)开关，闸，转换器","en":"A switch is a small control for an electrical device which you use to turn the device on or off.","ex":{"en":"Leona put some detergent into the dishwasher, shut the door and pressed the switch.","cn":"利昂娜将一些清洁剂放入洗碗机，关上门后按了开始键。"}},{"pos":"VERB 动词","cn":"转换;改变;转变","en":"If you switch to something different, for example to a different system, task, or subject of conversation, you change to it from what you were doing or saying before.","ex":{"en":"Estonia is switching to a market economy","cn":"爱沙尼亚正在向市场经济转轨。"}},{"pos":"V-ERG 及物/不及物动词","cn":"转移(注意力);(注意力)转变","en":"If you switch your attention from one thing to another or if your attention switches, you stop paying attention to the first thing and start paying attention to the second.","ex":{"en":"My mother's interest had switched to my health","cn":"母亲转而关注起我的健康来。"}},{"pos":"VERB 动词","cn":"交换;调换;对调","en":"If you switch two things, you replace one with the other.","ex":{"en":"In half an hour, they'd switched the tags on every cable","cn":"半个小时内，他们就给每根电缆都换了标签。"}},{"pos":"","cn":"","en":"相关词组：switch off switch on switch over"}]},"examples":[{"en":"Do you think she'll notice if I switch my glass with hers?","cn":"要是把我的杯子跟她的换了，你认为她看得出来吗？"},{"en":"She made the switch from full-time to part-time work when her first child was born.","cn":"第一个孩子出生后她就从全职工作改为兼职工作。"}]},"swallow":{"media":{"uk":"media/uk/swallow__gb_1.mp3","us":"media/us/swallow__us_1.mp3"},"oxford":{"phon":"ˈswɒləʊ","pos":"verb","senses":[{"en":"to make food, drink, etc. go down your throat into your stomach","cn":"吞下；咽下","g":"[transitive, intransitive]","sc":"food/drink","ex":{"en":"Always chew food well before swallowing it.","cn":"什么食物都要先嚼碎再吞咽。"}},{"en":"to move the muscles of your throat as if you were swallowing something, especially because you are nervous","cn":"（由于紧张等）做吞咽动作","g":"[intransitive]","sc":"move throat muscles","ex":{"en":"She swallowed hard and told him the bad news.","cn":"她使劲咽了口唾沫，把坏消息告诉了他。"}},{"en":"to take somebody/something in or completely cover them/it so that they/it cannot be seen or exist separately any longer","cn":"吞没；淹没；侵吞","g":"[transitive, often passive]","sc":"completely cover","ex":{"en":"I watched her walk down the road until she was swallowed by the darkness.","cn":"我看着她沿公路越走越远，直至消失在黑暗中。"}},{"en":"to use up something completely, especially an amount of money","cn":"用尽，耗尽，花光（尤指钱财）","g":"[transitive]","sc":"use up money","ex":{"en":"Most of my salary gets swallowed (up) by the rent and bills.","cn":"我的工资大多支付房租和各种日常费用了。"}},{"en":"to accept that something is true; to believe something","cn":"相信；信以为真","g":"[transitive]","sc":"believe","ex":{"en":"I found her excuse very hard to swallow.","cn":"我觉得她的理由很难让人相信。"}},{"en":"to hide your feelings","cn":"不流露；掩饰；抑制","g":"[transitive]","sc":"feelings","ex":{"en":"to swallow your doubts","cn":"不流露怀疑"}},{"en":"to accept offensive remarks, criticisms, etc. without complaining or protesting","cn":"默默忍受（侮辱、批评等）","g":"[transitive]","sc":"accept insults","ex":{"en":"I was surprised that he just sat there and swallowed all their remarks.","cn":"让我吃惊的是他就坐在那儿默默地任凭他们评论。"}},{"en":"a small bird, with long pointed wings and a tail with two points, that migrates (= moves from one part of the world to another according to the season)","cn":"燕","sc":"bird","pos":"noun"},{"en":"an act of swallowing; an amount of food or drink that is swallowed at one time","cn":"咽；吞；一次吞咽的量；一口","sc":"of food/drink","ex":{"en":"She took a swallow of coffee.","cn":"她喝了一口咖啡。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吞下;咽下","en":"If you swallow something, you cause it to go from your mouth down into your stomach.","ex":{"en":"You are asked to swallow a capsule containing vitamin B","cn":"你要服一粒维生素 B 胶囊。"}},{"pos":"VERB 动词","cn":"(常因为紧张或恐惧而)做吞咽动作，咽口水","en":"If you swallow, you make a movement in your throat as if you are swallowing something, often because you are nervous or frightened.","ex":{"en":"Nancy swallowed hard and shook her head.","cn":"南希用力咽了口口水，摇了摇头。"}},{"pos":"VERB 动词","cn":"完全相信;信以为真","en":"If someone swallows a story or a statement, they believe it completely.","ex":{"en":"It was vital that he swallowed the story about Juanita being in that motel room that night.","cn":"关键是他对朱厄妮塔那晚住在那个汽车旅馆房间里一事毫不怀疑。"}},{"pos":"VERB 动词","cn":"掩饰，抑制(感情)","en":"If you swallow your feelings, you do not express them, although you want to very much.","ex":{"en":"Gordon has swallowed the anger he felt","cn":"戈登忍住了内心的愤怒。"}},{"pos":"N-COUNT 可数名词","cn":"燕子","en":"A swallow is a kind of small bird with pointed wings and a forked tail."},{"pos":"","cn":"","en":"a bitter pill to swallow→see: ; to swallow one's pride→see: ;"},{"pos":"","cn":"","en":"相关词组：swallow up"}]},"examples":[{"en":"I was surprised that he just sat there and swallowed all their remarks.","cn":"让我吃惊的是他就坐在那儿默默地任凭他们评论。"},{"en":"I watched her walk down the road until she was swallowed by the darkness.","cn":"我看着她沿公路越走越远，直至消失在黑暗中。"}]},"swells":{"oxford":{"phon":"swel","pos":"verb","senses":[{"en":"to become bigger or rounder","cn":"膨胀；肿胀"},{"en":"to curve out or make sth curve out （","cn":"使）凸出，鼓出"}]}},"switching":{"oxford":{"phon":"swɪtʃ","pos":"noun","senses":[{"en":"a small device that you press or move up and down in order to turn a light or piece of electrical equipment on and off （","cn":"电路的）开关，闸，转换器"},{"en":"a change from one thing to another, especially when this is sudden and complete （","cn":"尤指突然彻底的）改变，转变"}]}},"swapping":{"oxford":{"phon":"swɒp","pos":"verb","senses":[{"en":"to give sth to sb and receive sth in exchange","cn":"交换（东西）"},{"en":"to start doing sb else's job, etc. while they do yours","cn":"交换（工作）"}]}},"sweetened":{"oxford":{"phon":"ˈswiːtn","pos":"verb","senses":[{"en":"to make food or drinks taste sweeter by adding sugar, etc.","cn":"使变甜；加糖于"},{"en":"( informal ) to try to make sb more willing to help you, agree to sth, etc. by giving them money, praising them, etc.","cn":"讨好；拉拢；哄；收买；恭维"}]}},"swimmers":{"oxford":{"phon":"ˈswɪmə(r)","pos":"noun","senses":[{"en":"a person who can swim; a person who is swimming","cn":"会游泳者；游泳者"}]}},"sweaters":{"oxford":{"phon":"ˈswetə(r)","pos":"noun","senses":[{"en":"a knitted piece of clothing made of wool or cotton for the upper part of the body, with long sleeves. In British English the word is used to describe a piece of clothing with no buttons. In American English a sweater can have butt","cn":"毛衣，线衣（英式英语指套头无扣的；美式英语可指开襟有扣的）"}]}},"swirls":{"oxford":{"phon":"swɜːl","pos":"verb","senses":[{"en":"to move around quickly in a circle; to make sth do this （","cn":"使）打旋，旋动，起漩涡"},{"en":"the movement of sth that twists and turns in different directions and at different speeds","cn":"打旋；旋动；漩涡"}]}},"switches":{"oxford":{"phon":"swɪtʃ","pos":"noun","senses":[{"en":"a small device that you press or move up and down in order to turn a light or piece of electrical equipment on and off （","cn":"电路的）开关，闸，转换器"},{"en":"a change from one thing to another, especially when this is sudden and complete （","cn":"尤指突然彻底的）改变，转变"}]}},"swarmed":{"oxford":{"phon":"swɔːm","pos":"noun","senses":[{"en":"a large group of insects, especially bees , moving together in the same direction","cn":"一大群（蜜蜂等昆虫）"},{"en":"a large group of people, especially when they are all moving quickly in the same direction","cn":"一大群，一大批（向同方向移动的人）"}]}},"swamped":{"oxford":{"phon":"swɒmp","pos":"noun","senses":[{"en":"an area of ground that is very wet or covered with water and in which plants, trees, etc. are growing","cn":"沼泽（地）"},{"en":"to make sb have more of sth than they can deal with","cn":"使不堪承受；使疲于应对；使应接不暇"}]}},"switched":{"oxford":{"phon":"swɪtʃ","pos":"noun","senses":[{"en":"a small device that you press or move up and down in order to turn a light or piece of electrical equipment on and off （","cn":"电路的）开关，闸，转换器"},{"en":"a change from one thing to another, especially when this is sudden and complete （","cn":"尤指突然彻底的）改变，转变"}]}},"swastika":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"卐字饰，万字饰(印度的一种吉祥标志，同时也曾是德国纳粹党的党徽)","en":"A swastika is a symbol in the shape of a cross with each arm bent over at right angles. It is used in India as a good luck sign, but it was also used by the Nazis in Germany as their official symbol."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sign consisting of a cross with each end bent at 90º, used as a sign for the Nazi Party in Germany","cn":"卐字﹐万字符〔德国纳粹党的党徽〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41swastika.mp3","us":"media/ldoce/hwd/ame/9/swastika.mp3"},"oxford":{"phon":"ˈswɒstɪkə","pos":"noun","senses":[{"en":"an ancient symbol in the form of a cross with its ends bent at an angle of 90°, used in the 20th century as the symbol of the German Nazi party","cn":"万字符"}]}},"swarm":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(蜜蜂等昆虫的)一大群，一大窝","en":"A swarm of bees or other insects is a large group of them flying together."},{"pos":"VERB 动词","cn":"(蜜蜂等)成群飞行","en":"When bees or other insects swarm, they move or fly in a large group.","ex":{"en":"A dark cloud of bees comes swarming out of the hive.","cn":"黑压压的一大群蜜蜂从蜂巢中飞出来。"}},{"pos":"VERB 动词","cn":"(人)成群地涌动，蜂拥","en":"When people swarm somewhere, they move there quickly in a large group.","ex":{"en":"People swarmed to the shops, buying up everything in sight.","cn":"人们成群地涌向商店，见什么买什么。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"(快速移动的)人群","en":"A swarm of people is a large group of them moving about quickly.","ex":{"en":"A swarm of people encircled the hotel","cn":"一大群人围住了这个酒店。"}},{"pos":"VERB 动词","cn":"挤满，聚集(来来往往的人)","en":"If a place is swarming with people, it is full of people moving about in a busy way.","ex":{"en":"Within minutes the area was swarming with officers who began searching a nearby wood.","cn":"几分钟内很多警察就来到了这一地区，开始搜查附近的树林。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large number of people together in one place","cn":""},{"en":"a crowd of noisy and violent people who are difficult to control","cn":""},{"en":"a very large crowd which is not moving and which is very difficult to move through","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A swarm is a good word for a large group of bees going on the attack — not good news. Like bees, any group of people or animals can be considered a swarm if they act together and quickly — even fiercely."}]},"media":{"uk":"media/ldoce/hwd/bre/7/swarm_n0205.mp3","us":"media/ldoce/hwd/ame/d/swarm1.mp3"},"examples":[{"en":"Tourists were swarming all over the island.","cn":"岛上到处是旅游者熙来攘往。"},{"en":"The capital city is swarming with police.","cn":"首都到处是警察。"}],"oxford":{"phon":"swɔːm","pos":"noun","senses":[{"en":"a large group of insects, especially bees, moving together in the same direction","cn":"一大群（蜜蜂等昆虫）","ex":{"en":"a swarm of bees/locusts/flies","cn":"一大群蜜蜂／蝗虫／苍蝇"}},{"en":"a large group of people, especially when they are all moving quickly in the same direction","cn":"一大群，一大批（向同方向移动的人）"},{"en":"to move around in a large group","cn":"成群地来回移动","g":"[intransitive]","lab":"often disapproving","ex":{"en":"Tourists were swarming all over the island.","cn":"岛上到处是旅游者熙来攘往。"},"pos":"verb"},{"en":"to move around together in a large group, looking for a place to live","cn":"成群地飞来飞去","pos":"verb"}]}},"sweltering":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"炎热的;酷热的;热得难受的","en":"If you describe the weather as sweltering, you mean that it is extremely hot and makes you feel uncomfortable."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"high temperatures caused by hot weather, especially when this makes you feel uncomfortable in a room or outdoors","cn":""},{"en":"very hot","cn":""},{"en":"very hot and uncomfortable","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Sweltering means uncomfortably hot. Walking home from work on a sweltering day will leave you sweating."}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdesweltering.mp3","us":"media/ldoce/hwd/ame/8/sweltering.mp3"},"examples":[{"en":"sweltering heat","cn":"酷热难耐的高温"},{"en":"sweltering August days","cn":"酷热难耐的八月天"}],"oxford":{"phon":"ˈsweltərɪŋ","pos":"adjective","senses":[{"en":"very hot in a way that makes you feel uncomfortable","cn":"炎热的，酷热的","ex":{"en":"sweltering heat","cn":"酷热"}}]}},"swimwear":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"泳装","en":"Swimwear is the things people wear for swimming."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"clothing used for swimming","cn":"游泳衣，泳装"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41swimwear.mp3","us":"media/ldoce/hwd/ame/d/laadswimwear.mp3"},"oxford":{"phon":"ˈswɪmweə(r)","pos":"noun","senses":[{"en":"clothing that you wear for swimming","cn":"游泳衣；泳装","ex":{"en":"a new swimwear collection","cn":"新的泳装系列"}}]}},"sweetheart":{"collins":{"senses":[{"pos":"N-VOC 称呼名词","cn":"亲爱的;宝贝儿","en":"You call someone sweetheart if you are very fond of them.","ex":{"en":"Happy birthday, sweetheart.","cn":"生日快乐，亲爱的。"}},{"pos":"N-COUNT 可数名词","cn":"恋人;情人","en":"Your sweetheart is your boyfriend or your girlfriend.","ex":{"en":"I married Shurla, my childhood sweetheart, in Liverpool.","cn":"我在利物浦和我青梅竹马的恋人舒拉结婚了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a boy or man that you have a romantic relationship with, especially for a fairly long time","cn":""},{"en":"the person you are married to, or the person you are living with and having a sexual relationship with","cn":""},{"en":"the man whom a woman is going to marry","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/sweetheart0205.mp3","us":"media/ldoce/hwd/ame/e/sweetheart.mp3"},"examples":[{"en":"Do you want a drink, sweetheart?","cn":"想喝一杯吗，亲爱的？"},{"en":"They were childhood sweethearts.","cn":"他们俩是青梅竹马。"}],"oxford":{"phon":"ˈswiːthɑːt","pos":"noun","senses":[{"en":"used to address somebody in a kind and loving way","cn":"（用作称呼语）亲爱的，宝贝儿","g":"[singular]","lab":"informal","ex":{"en":"Do you want a drink, sweetheart?","cn":"想喝一杯吗，亲爱的？"}},{"en":"a person with whom somebody is having a romantic relationship","cn":"恋人；爱人；心上人","g":"[countable]","lab":"becoming old-fashioned","ex":{"en":"They were childhood sweethearts.","cn":"他们俩是青梅竹马。"}}]}},"swindle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"诈骗,骗取，欺诈(尤指钱财)","en":"If someone swindles a person or an organization, they deceive them in order to get something valuable from them, especially money.","ex":{"en":"A City businessman swindled investors out of millions of pounds","cn":"一名来自伦敦商业区的商人骗取了投资者们数百万英镑。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deceive someone so that they do not get or keep something they have a right to","cn":""},{"en":"to get money from someone by telling them lies","cn":""},{"en":"to get money from a person or organization by cheating them in a clever way","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To swindle is to cheat or steal. You can swindle money, goods, ideas, and anything else that can be stolen, but be careful, because someone can also swindle you."}]},"media":{"uk":"media/ldoce/hwd/bre/2/swindle_v0205.mp3","us":"media/ldoce/hwd/ame/a/swindle1.mp3"},"examples":[{"en":"They swindled him out of hundreds of dollars.","cn":"他们诈骗了他好几百元。"},{"en":"They swindled hundreds of dollars out of him.","cn":"他们诈骗了他好几百元。"}],"oxford":{"phon":"ˈswɪndl","pos":"verb","senses":[{"en":"to cheat somebody in order to get something, especially money, from them","cn":"诈骗；骗取","ex":{"en":"They swindled him out of hundreds of dollars.","cn":"他们诈骗了他好几百美元。"}},{"en":"a situation in which somebody uses dishonest or illegal methods in order to get money from a company, another person, etc.","cn":"诈骗；骗取","ex":{"en":"an insurance swindle","cn":"保险诈骗案"},"pos":"noun"}]}},"swirl":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)打旋;(使)旋动;(使)起旋涡","en":"If you swirl something liquid or flowing, or if it swirls, it moves round and round quickly.","ex":{"en":"She smiled, swirling the wine in her glass","cn":"她微笑着，旋动着杯子里的葡萄酒。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something turns , it moves around a fixed central point","cn":""},{"en":"to move in a continuous circular movement","cn":""},{"en":"to turn around many times very quickly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/swirl_v0205.mp3","us":"media/ldoce/hwd/ame/1/swirl1.mp3"},"examples":[{"en":"He took a mouthful of water and swirled it around his mouth.","cn":"他含了一口水，在嘴里转来转去。"},{"en":"A long skirt swirled around her ankles.","cn":"她的长裙在脚踝旁边摆动。"}],"oxford":{"phon":"swɜːl","pos":"verb","senses":[{"en":"to move around quickly in a circle; to make something do this","cn":"（使）打旋，旋动，起漩涡","ex":{"en":"The water swirled down the drain.","cn":"水打着漩流进了下水道。"}},{"en":"the movement of something that twists and turns in different directions and at different speeds","cn":"打旋；旋动；漩涡","ex":{"en":"The dancers left the stage in a swirl of skirts.","cn":"舞者们穿着裙子离开舞台。"},"pos":"noun"},{"en":"a pattern or an object that twists in circles","cn":"螺旋形；漩涡状（物体）","ex":{"en":"The material is yellow with blue swirls on it.","cn":"该材料为黄色，上面有蓝色漩涡。"},"pos":"noun"}]}},"sweatshop":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"血汗工厂(工作条件恶劣、工资低的小工厂)","en":"If you describe a small factory as a sweatshop, you mean that many people work there in poor conditions for low pay.","ex":{"en":"...the dingy, hidden world of garment sweatshops.","cn":"肮脏隐蔽的血汗服装工厂"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building or group of buildings in which goods are produced in large quantities, using machines","cn":""},{"en":"a large factory where cars, chemicals, or energy is produced","cn":""},{"en":"a factory. Facility is often used instead of factory in business English","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A sweatshop is a factory where workers are exploited and not allowed to unionize. You might not sweat in a sweatshop , but you probably work hard and under lousy conditions."}]},"media":{"uk":"media/ldoce/hwd/bre/0/sweatshop0205.mp3","us":"media/ldoce/hwd/ame/2/sweatshop.mp3"},"oxford":{"phon":"ˈswetʃɒp","pos":"noun","senses":[{"en":"a place where people work for low wages in poor conditions","cn":"血汗工厂，血汗工场（工资低廉、劳动条件恶劣）"}]}},"swamp":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"沼泽(地)","en":"A swamp is an area of very wet land with wild plants growing in it."},{"pos":"VERB 动词","cn":"淹没;浸没","en":"If something swamps a place or object, it fills it with water.","ex":{"en":"A rogue wave swamped the boat","cn":"凶猛的海浪淹没了船只。"}},{"pos":"VERB 动词","cn":"使不堪承受;使疲于应对;使应接不暇","en":"If you are swamped by things or people, you have more of them than you can deal with.","ex":{"en":"He is swamped with work","cn":"他工作忙得不可开交。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of low flat ground that is always wet and soft, that often has grasses or reed s growing in it but no trees","cn":""},{"en":"land that is always very wet or covered with a layer of water, that often has trees growing in it – used especially about areas in hot countries","cn":""},{"en":"an area of low wet muddy ground, sometimes with bushes or grasses growing in it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A swamp is an area that floods every year because the land is low. Watch out for alligators if you visit Atchafalaya National Wildlife Refuge in Louisiana, the largest swamp in the United States."}]},"media":{"uk":"media/ldoce/hwd/bre/2/swamp_n0205.mp3","us":"media/ldoce/hwd/ame/a/swamp1.mp3"},"examples":[{"en":"The department was swamped with job applications.","cn":"面对纷至沓来的求职申请，这个部门疲于应对。"},{"en":"In summer visitors swamp the island.","cn":"夏天，这个岛上游客熙熙攘攘，人满为患。"}],"oxford":{"phon":"swɒmp","pos":"noun","senses":[{"en":"an area of ground that is very wet or covered with water and in which plants, trees, etc. are growing","cn":"沼泽（地）","ex":{"en":"tropical swamps","cn":"热带沼泽"}},{"en":"to make somebody have more of something than they can deal with","cn":"使不堪承受；使疲于应对；使应接不暇","ex":{"en":"The department was swamped with job applications.","cn":"面对纷至沓来的求职申请，这个部门疲于应对。"},"pos":"verb"},{"en":"to fill or cover something with a lot of water","cn":"淹；淹没","ex":{"en":"The little boat was swamped by the waves.","cn":"小船被大浪淹没了。"},"pos":"verb"}]}},"swat":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拍，击，打(昆虫等)","en":"If you swat something such as an insect, you hit it with a quick, swinging movement, using your hand or a flat object.","ex":{"en":"Hundreds of flies buzz around us, and the workman keeps swatting them.","cn":"数百只苍蝇围着我们转，工作人员不停地拍打。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit an insect in order to kill it","cn":"重拍﹐猛击〔昆虫〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/swat0205.mp3","us":"media/ldoce/hwd/ame/7/swat1.mp3"},"examples":[{"en":"He calmly swatted a couple of flies.","cn":"他冷静地拍死了几只苍蝇。"}],"oxford":{"phon":"swɒt","pos":"verb","senses":[{"en":"to hit something, especially an insect, using your hand or a flat object","cn":"拍，打（尤指昆虫）","ex":{"en":"He was trying to swat a fly with a rolled-up newspaper.","cn":"他正试图用卷起来的报纸拍苍蝇。"}},{"en":"an act of hitting or trying to hit something, especially an insect, using your hand or a flat object","cn":"拍，打（昆虫等）","ex":{"en":"She took a swat at the wasp.","cn":"她拍了黄蜂一巴掌。"},"pos":"noun"}]}},"swinger":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"时髦活跃的人","en":"A swinger is a person who is lively and fashionable."},{"pos":"N-COUNT 可数名词","cn":"交换性伴侣者;滥交者","en":"Swingers are people who are married or in a long-term relationship and who like to have sex with other couples."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is fashionable and goes to a lot of parties","cn":"活跃而时髦的人﹐常参加社交聚会的人"},{"en":"someone who has sexual relationships with many people, especially someone who exchanges sexual partners with other people","cn":"滥交的人﹐放荡的人；〔尤指〕交换性伴侣者"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41swinger.mp3","us":"media/ldoce/hwd/ame/0/swinger.mp3"},"oxford":{"phon":"ˈswɪŋə(r)","pos":"noun","senses":[{"en":"a person who is fashionable and has an active social life","cn":"时髦活跃的人物"},{"en":"a person who takes part in group sex or exchanging sexual partners","cn":"参加群体性交者；交换性伴侣者"}]}},"swampy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(指地面)湿软的，沼泽地的","en":"A swampy area of land is always very wet."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of low flat ground that is always wet and soft, that often has grasses or reed s growing in it but no trees","cn":""},{"en":"land that is always very wet or covered with a layer of water, that often has trees growing in it – used especially about areas in hot countries","cn":""},{"en":"an area of low wet muddy ground, sometimes with bushes or grasses growing in it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/swamp_n0205.mp3","us":"media/ldoce/hwd/ame/a/swamp1.mp3"},"oxford":{"phon":"ˈswɒmpi","pos":"adjective","senses":[{"en":"very wet or covered with water and in which plants, trees, etc. are growing","cn":"沼泽（地）","ex":{"en":"swampy ground/land","cn":"沼泽地/土地"}}]}},"sweatpants":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"运动裤","en":"Sweatpants are the part of a sweatsuit that covers your legs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"loose warm trousers, worn especially for sport or relaxation 〔","cn":"宽松保暖的〕运动长裤"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sweatpants.mp3","us":"media/ldoce/hwd/ame/a/ld41sweatpants.mp3"},"oxford":{"phon":"ˈswetpænts","pos":"noun","senses":[{"en":"loose, warm trousers, usually made of thick cotton and worn for relaxing or playing sports in","cn":"（厚长）运动裤"}]}},"swanky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时髦的;奢华的","en":"If you describe something as swanky, you mean that it is fashionable and expensive.","ex":{"en":"...one of the swanky hotels that line the Pacific shore at Acapulco.","cn":"坐落在太平洋沿岸的阿卡普尔科的豪华酒店之一"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very fashionable and expensive","cn":"非常时髦的﹔奢华的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/swanky0205.mp3","us":"media/ldoce/hwd/ame/e/swanky.mp3"},"examples":[{"en":"a swanky new hotel","cn":"时髦豪华的新旅馆"},{"en":"eating meals at swanky hotels","cn":"在豪华酒店吃饭"}],"oxford":{"phon":"ˈswæŋki","pos":"adjective","senses":[{"en":"fashionable and expensive in a way that is intended to impress people","cn":"摆阔的；时髦且豪华的","ex":{"en":"a swanky new hotel","cn":"时髦豪华的新旅馆"}}]}},"sweatsuit":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"运动服","en":"A sweatsuit is a loose, warm, stretchy suit consisting of long trousers and a top which people wear to relax and do exercise."}]},"oxford":{"phon":"ˈswetsuːt","pos":"noun","senses":[{"en":"a sweatshirt and sweatpants worn together, for relaxing or playing sports in","cn":"（长袖）运动套装"}]}},"sweetness":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"(关系)友好;(情况)令人愉快，顺利","en":"If you say that a relationship or situation is not all sweetness and light, you mean that it is not as pleasant as it appears to be.","ex":{"en":"It has not all been sweetness and light between him and the Prime Minister.","cn":"他和首相的关系并不总是那么愉快融洽。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how sweet something tastes or smells","cn":"甜﹔芬芳"},{"en":"how pleasant something is","cn":"愉悦﹐美好"},{"en":"to behave in a way that is very pleasant and friendly, especially when you do not normally behave like this 〔","cn":"尤指一反常态地〕和蔼可亲﹐亲切友善"}]},"collocations":{"phrases":["ADJ. natural | cloying, sickly | lingering the lingering sweetness of incense","QUANT. hint This is a full-bodied wine with just a hint of sweetness.","VERB + SWEETNESS taste 2 pleasantness","ADJ. exquisite, great | saccharine (= false) She smiled with saccharine sweetness.","VERB + SWEETNESS taste to taste the sweetness of military success","PHRASES all sweetness and light People think she's all sweetness and light, but she's actually got an awful temper."]},"media":{"uk":"media/ldoce/hwd/bre/6/sweetness0205.mp3","us":"media/ldoce/hwd/ame/8/laadsweetness.mp3"},"examples":[{"en":"The air was filled with the sweetness of mimosa.","cn":"空气中弥漫着含羞草的芬芳。"},{"en":"a smile of great sweetness","cn":"十分甜蜜的微笑"}],"oxford":{"phon":"ˈswiːtnəs","pos":"noun","senses":[{"en":"the quality of being pleasant","cn":"令人愉快；讨人喜欢","ex":{"en":"a smile of great sweetness","cn":"十分甜蜜的微笑"}},{"en":"the quality of tasting or smelling sweet","cn":"甜；芬芳","ex":{"en":"The air was filled with the sweetness of mimosa.","cn":"空气中弥漫着含羞草的芬芳。"}}]}},"swingeing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(抨击等)尖锐的,猛烈的;(削减)大幅度的，严重的","en":"A swingeing action, such as an attack or cut, is very great or severe.","ex":{"en":"...the book mounted a swingeing attack on the materialist, growth-oriented economics of the day","cn":"该书对当今追逐实利、以增长为导向的经济学进行了猛烈的抨击"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very severe reductions in spending, especially by a government or organization 〔","cn":"尤指政府或组织的〕大幅开支削减"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41swingeing.mp3","us":"media/ldoce/hwd/ame/6/ld41swingeing.mp3"},"examples":[{"en":"a swingeing attack on government policy","cn":"猛烈抨击政府的政策"},{"en":"swingeing cuts in benefits","cn":"补助金的大量削减"}],"oxford":{"phon":"ˈswɪndʒɪŋ","pos":"adjective","senses":[{"en":"large and likely to cause people problems, especially financial problems","cn":"巨额的；严重的；巨大的","ex":{"en":"swingeing cuts in benefits","cn":"补助金的大量削减"}},{"en":"extremely critical of somebody/something","cn":"尖锐的；猛烈的","ex":{"en":"a swingeing attack on government policy","cn":"猛烈抨击政府的政策"}}]}},"swig":{"collins":{"senses":[{"pos":"VERB 动词","cn":"大口喝;畅饮","en":"If you swig a drink, you drink it from a bottle or cup quickly and in large amounts.","ex":{"en":"I swigged down two white wines","cn":"我把两杯白葡萄酒一饮而尽。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to drink something very slowly","cn":""},{"en":"to drink something in a noisy way","cn":""},{"en":"to drink all of something very quickly","cn":""}]},"collocations":{"phrases":["ADJ. deep, good, long | quick","VERB + SWIG have, take","PREP. ~ from He took a deep swig from the bottle. | ~ of She had a quick swig of water and then set off again."]},"media":{"uk":"media/ldoce/hwd/bre/7/swig0205.mp3","us":"media/ldoce/hwd/ame/2/swig.mp3"},"examples":[{"en":"They sat around swigging beer from bottles.","cn":"他们闲坐着，对着瓶子大口地喝啤酒。"},{"en":"She took a swig of wine.","cn":"她喝了一大口葡萄酒。"}],"oxford":{"phon":"swɪɡ","pos":"verb","senses":[{"en":"to take a quick drink of something, especially alcohol","cn":"大口喝（酒等）","ex":{"en":"They sat around swigging beer from bottles.","cn":"他们闲坐着，对着瓶子大口地喝啤酒。"}},{"en":"an amount of something, especially alcohol, that you swallow or drink quickly","cn":"大口喝（酒等）","ex":{"en":"She took a swig of wine.","cn":"她喝了一大口葡萄酒。"},"pos":"noun"}]}},"sworn":{"collins":{"senses":[{"pos":"","cn":"","en":"Sworn is the past participle of swear ."},{"pos":"ADJ 形容词","cn":"(陈述、声明)宣过誓的，宣誓证明的","en":"If you make a sworn statement or declaration, you swear that everything that you have said in it is true.","ex":{"en":"The allegations against them were made in sworn evidence to the inquiry.","cn":"在调查取得的宣誓证词中对他们提出了指控。"}},{"pos":"ADJ 形容词","cn":"(仇敌)不共戴天的,势不两立的","en":"If two people or two groups of people are sworn enemies, they dislike each other very much.","ex":{"en":"It somehow seems hardly surprising that Ms Player is now his sworn enemy.","cn":"现在普莱耶女士成了他不共戴天的仇敌反倒让人觉得不足为奇了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the past participle of swear swear","cn":"的过去分词"},{"en":"two people or groups of people who will always hate each other","cn":"不共戴天的死敌"},{"en":"a statement etc that someone makes after officially promising to tell the truth","cn":"宣誓后的陈述/证据/证词等"}]},"media":{"uk":"media/ldoce/hwd/bre/3/sworn0205.mp3","us":"media/ldoce/hwd/ame/a/sworn1.mp3"},"examples":[{"en":"a sworn statement","cn":"宣誓证词"}],"oxford":{"phon":"swɔːn","pos":"adjective","senses":[{"en":"made after you have promised to tell the truth, especially in court","cn":"（尤指在法庭上）宣过誓的，宣誓证明的","ex":{"en":"a sworn statement","cn":"宣誓证词"}},{"en":"people, countries, etc. that are determined to hate each other","cn":"不共戴天的仇敌"}]}},"swordsman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"剑客;剑手","en":"A swordsman is a man who is skilled at fighting with a sword."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is good at fighting with a sword","cn":"剑客﹐剑手"},{"en":"a man who has sex very often and with a lot of different women","cn":"滥交的男人"}]},"vocab":{"pos":"n","senses":[{"en":"A swordsman is a person who is very good at swordplay or fencing. If you are looking to find a swordsman , you should look among Shakespeare's characters."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41swordsman.mp3","us":"media/ldoce/hwd/ame/5/swordsman.mp3"},"examples":[{"en":"a fine swordsman","cn":"剑术高超的剑客"}],"oxford":{"phon":"ˈsɔːdzmən","pos":"noun","senses":[{"en":"(usually used with an adjective) a person who fights with a sword","cn":"（通常与形容词连用）剑客，剑手","ex":{"en":"a fine swordsman","cn":"剑术高超的剑客"}}]}},"swelling":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(身体因受伤或患病产生的)肿胀,浮肿","en":"A swelling is a raised, curved shape on the surface of your body which appears as a result of an injury or an illness.","ex":{"en":"His eye was partly closed, and there was a swelling over his lid","cn":"他的眼睛半闭着，眼睑上有一个肿块。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of your body that has become larger than normal, because of illness or injury 〔","cn":"身体因患病或受伤产生的〕肿块﹐肿胀处"},{"en":"the condition of having swelled","cn":"膨胀﹔肿胀"}]},"collocations":{"phrases":["ADJ. marked There is a marked swelling of the lymph nodes. | slight","VERB + SWELLING reduce","SWELLING + VERB occur | go down, subside"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeswelling.mp3","us":"media/ldoce/hwd/ame/4/swelling.mp3"},"examples":[{"en":"The fall left her with a painful swelling above her eye.","cn":"她摔了一跤，眼睛上方起了一个包，挺疼的。"},{"en":"Use ice to reduce the swelling.","cn":"用冰敷消肿。"}],"oxford":{"phon":"ˈswelɪŋ","pos":"noun","senses":[{"en":"the condition of being larger or rounder than normal (= of being swollen)","cn":"膨胀；肿胀","g":"[uncountable]","ex":{"en":"Use ice to reduce the swelling.","cn":"用冰敷消肿。"}},{"en":"a place on your body that has become larger or rounder than normal as the result of an illness or injury","cn":"肿胀处；浮肿处","g":"[countable]","ex":{"en":"The fall left her with a painful swelling above her eye.","cn":"她摔了一跤，眼睛上方起了一个包，挺疼的。"}}]}},"swop":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a British spelling of swap swap","cn":"的英式拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41swop.mp3","us":"media/ldoce/hwd/ame/f/ld41swop.mp3"},"oxford":{"phon":"swɒp","pos":"verb","senses":[{"en":"to give something to somebody and receive something in exchange","cn":"交换（东西）","g":"[intransitive, transitive]","ex":{"en":"I've finished this magazine. Can I swop with you?","cn":"我已经读完了这本杂志。我可以和你交换吗？"}},{"en":"to start doing somebody else’s job, etc. while they do yours","cn":"交换（工作）","g":"[intransitive]","ex":{"en":"I'll drive there and then we'll swop over on the way back.","cn":"我会开车去那里，然后我们在回来的路上交换。"}},{"en":"to replace one person or thing with another","cn":"用…替换；把…换成；掉换","g":"[transitive]","lab":"especially British English","ex":{"en":"I think I'll swop this sweater for one in another colour.","cn":"我想我会把这件毛衣换成另一种颜色的。"}},{"en":"an act of exchanging one thing or person for another","cn":"交换；掉换","g":"[usually singular]","ex":{"en":"Let's do a swop. You work Friday night and I'll do Saturday.","cn":"我们来进行一次交换吧。你周五晚上工作，我周六工作。"},"pos":"noun"},{"en":"a thing or person that has been exchanged for another","cn":"交换物；被掉换者","ex":{"en":"Most of my football stickers are swops.","cn":"我的大部分足球贴纸都是交换的。"},"pos":"noun"}]}},"swab":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(医用)拭子，棉签，药签","en":"A swab is a small piece of cotton wool used by a doctor or nurse for cleaning a wound or putting a substance on it."},{"pos":"VERB 动词","cn":"(用拖把、抹布等)擦洗，擦拭","en":"If you swab something, you clean it using a wet cloth or a tool called a mop.","ex":{"en":"I noticed a lone man in the cafeteria swabbing the floor as I passed.","cn":"我路过时注意到一个男子独自在自助餐厅里拖地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of material used to clean a wound or take a small amount of a substance from someone’s body in order to test it 〔","cn":"医用〕拭子﹐药棉棒"},{"en":"a small amount of a substance that is taken from someone’s body with a swab in order to test it 〔","cn":"用拭子采集的〕化验样本"},{"en":"to clean something using a large amount of water","cn":"擦洗﹐擦拭"}]},"media":{"uk":"media/ldoce/hwd/bre/b/swab_n0205.mp3","us":"media/ldoce/hwd/ame/1/swab1.mp3"},"examples":[{"en":"to take a throat swab","cn":"用棉签从咽部采集化验样品"},{"en":"The doctor took a throat swab to check for infection.","cn":"医生用拭子从咽喉取样检查是否有感染。"}],"oxford":{"phon":"swɒb","pos":"noun","senses":[{"en":"a piece of soft material used by a doctor, nurse, etc. for cleaning wounds or taking a sample from somebody’s body for testing","cn":"（医用的）拭子，药签"},{"en":"an act of taking a sample from somebody’s body, with a swab","cn":"用拭子对（人体）化验标本的采集","ex":{"en":"to take a throat swab","cn":"采集咽拭子标本"}},{"en":"to clean or remove liquid from a wound, etc., using a swab","cn":"用拭子擦拭","pos":"verb"},{"en":"to clean or wash a floor, surface, etc. using water and a cloth, etc.","cn":"擦洗，擦拭（地板等）","ex":{"en":"I swabbed down the table using disinfectant.","cn":"我用消毒剂擦拭桌子。"},"pos":"verb"}]}},"swimmingly":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"进展顺利;一帆风顺","en":"If you say that something is going swimmingly, you mean that everything is happening in a satisfactory way, without any problems.","ex":{"en":"The work has been going swimmingly.","cn":"工作进展得一直很顺利。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if something you plan goes swimmingly, it happens without problems","cn":"顺利地进行﹐一帆风顺"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41swimmingly.mp3","us":"media/ldoce/hwd/ame/6/swimmingly.mp3"},"examples":[{"en":"We hope everything will go swimmingly.","cn":"我们希望一切进展顺利。"}],"oxford":{"phon":"ˈswɪmɪŋli","pos":"adverb","senses":[{"en":"without any problems or difficulties","cn":"顺利地；顺顺当当地","ex":{"en":"We hope everything will go swimmingly.","cn":"我们希望一切进展顺利。"}}]}},"swashbuckling":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"传奇的;历经艰险的;惊心动魄的","en":"If you describe someone or something as swashbuckling, you mean that they are connected with adventure and excitement.","ex":{"en":"He has not been the same swashbuckling player since suffering a knee injury.","cn":"自从膝盖受伤后他就不再是那个传奇的运动员了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to adventures in which people do brave exciting things and fight against their enemies with swords","cn":"传奇历险的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41swashbuckling.mp3","us":"media/ldoce/hwd/ame/9/swashbuckling.mp3"},"examples":[{"en":"the swashbuckling hero of Hollywood epics","cn":"好莱坞史诗片中的传奇英雄"},{"en":"a swashbuckling tale of adventure on the high seas","cn":"公海上的传奇历险故事"}],"oxford":{"phon":"ˈswɒʃbʌklɪŋ","pos":"adjective","senses":[{"en":"set in the past and full of action, adventure, fighting with swords, etc.","cn":"表现古代惊险打斗的；有传奇历险情节的","ex":{"en":"a swashbuckling tale of adventure on the high seas","cn":"公海上的传奇历险故事"}}]}},"sweetmeat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指特殊的)甜食,糖果，果脯","en":"Sweetmeats are sweet items of food, especially ones that are considered special."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sweet , or any food made of or preserved in sugar","cn":"糖果﹔甜食﹔蜜饯"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41sweetmeat.mp3","us":"media/ldoce/hwd/ame/e/ld41sweetmeat.mp3"},"oxford":{"phon":"ˈswiːtmiːt","pos":"noun","senses":[{"en":"a sweet; any food preserved in sugar","cn":"糖果；蜜饯；果脯"}]}},"sweet-talk":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to persuade someone to do something that you want them to do by being very nice to them, making them laugh etc","cn":""},{"en":"to persuade someone to do something that they do not want to do by talking to them gently for a long time until they agree to do it","cn":""},{"en":"to say nice things to someone, especially things that are not true, in order to persuade them to do something for you","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41sweet-talk.mp3","us":"media/ldoce/hwd/ame/e/sweet-talk.mp3"},"examples":[{"en":"I can't believe you let him sweet-talk you into working for him!","cn":"我无法相信，他几句好话就哄得你为他效力！"},{"en":"I managed to sweet-talk her into driving me home.","cn":"我说了一堆好话终于让她开车送我回家。"}],"oxford":{"phon":"ˈswiːt tɔːk","pos":"noun","senses":[{"en":"praise and nice things that somebody says to try to persuade somebody to do something","cn":"甜言蜜语：赞美和别人说的好话，试图说服别人做某事"},{"en":"to try to persuade somebody to do something by praising them and telling them things they like to hear","cn":"对…甜言蜜语；给…灌迷魂汤","ex":{"en":"I can't believe you let him sweet-talk you into working for him!","cn":"我无法相信，他几句好话就哄得你为他效力！"},"pos":"verb"}]}},"swordfish":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"箭鱼;剑鱼","en":"A swordfish is a large sea fish with a very long upper jaw.","ex":{"en":"...grilled swordfish with a yogurt dressing.","cn":"浇酸奶酪汁的烤箭鱼"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large fish with a very long pointed upper jaw","cn":"剑鱼"}]},"media":{"uk":"media/ldoce/hwd/bre/f/swordfish0205.mp3","us":"media/ldoce/hwd/ame/e/swordfish.mp3"},"oxford":{"phon":"ˈsɔːdfɪʃ","pos":"noun","senses":[{"en":"a large sea fish with a very long, thin, pointed upper jaw","cn":"箭鱼；剑鱼","ex":{"en":"swordfish steaks","cn":"旗鱼排"}}]}},"swerve":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)突然转向;(使)急转弯","en":"If a vehicle or other moving thing swerves or if you swerve it, it suddenly changes direction, often in order to avoid hitting something.","ex":{"en":"Drivers coming in the opposite direction swerved to avoid the bodies","cn":"从对面来的汽车司机急忙转向以免撞到那些尸体。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change your direction when you are walking or driving","cn":""},{"en":"to turn while you are moving so that you start going in a different direction","cn":""},{"en":"if a vehicle, ship, or aircraft changes course , it changes the direction in which it is travelling","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The noun swerve means a sudden turn off your path. As a verb, it means to move off your original route, possibly to avoid a collision. You can swerve either toward something or away from it."}]},"collocations":{"phrases":["ADJ. sudden The car made a sudden swerve to the left.","VERB + SWERVE make"]},"media":{"uk":"media/ldoce/hwd/bre/7/swerve0205.mp3","us":"media/ldoce/hwd/ame/e/swerve1.mp3"},"examples":[{"en":"She swerved sharply to avoid a cyclist.","cn":"她猛地急转弯，以避开一个骑自行车的人。"},{"en":"The ball swerved into the net.","cn":"球在空中划了一条弧线，进了球门。"}],"oxford":{"phon":"swɜːv","pos":"verb","senses":[{"en":"to change direction suddenly, especially in order to avoid hitting somebody/something","cn":"突然转向；急转弯","ex":{"en":"She swerved sharply to avoid a cyclist.","cn":"她猛地急转弯，以避开一个骑自行车的人。"}},{"en":"a sudden change of direction by a vehicle, especially in order to avoid hitting somebody/something","cn":"突然转向；急转弯","ex":{"en":"The bus made a sudden swerve to the left.","cn":"公共汽车突然向左转弯。"},"pos":"noun"}]}},"swoop":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(警察或士兵)突击搜查，突然袭击","en":"If police or soldiers swoop on a place, they go there suddenly and quickly, usually in order to arrest someone or to attack the place.","ex":{"en":"The terror ended when armed police swooped on the car","cn":"武警突袭了这辆车从而制止了这起恐怖活动。"}},{"pos":"VERB 动词","cn":"(鸟或飞机)向下猛冲，俯冲","en":"When a bird or aeroplane swoops, it suddenly moves downwards through the air in a smooth curving movement.","ex":{"en":"More than 20 helicopters began swooping in low over the ocean","cn":"20 多架直升机开始下降向海面俯冲。"}},{"pos":"PHRASE 短语","cn":"一下子; 一举","en":"If something is done in one fell swoop or at one fell swoop, it is done on a single occasion or by a single action.","ex":{"en":"In one fell swoop the bank wiped away the tentative benefits of this policy.","cn":"银行一下子就抹杀了这项政策暂时带来的好处。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a bird or aircraft swoops, it moves suddenly down through the air, especially in order to attack something 〔","cn":"鸟或飞机〕向下猛冲﹐向下猛扑"},{"en":"if the police, army etc swoop on a place, they go there without any warning in order to look for someone or something 〔","cn":"警方﹑军队等〕突然袭击，突然搜查"},{"en":"a sudden surprise attack on a place in order to get something or take people away – used especially in news reports","cn":"突然袭击，突击搜查〔尤用于新闻报道〕"}]},"vocab":{"pos":"v n","senses":[{"en":"To swoop is to move downward quickly and dramatically, like an eagle that swoops down to catch its prey."}]},"collocations":{"phrases":["ADV. low An eagle swooped low over the trees. | suddenly | down, in","PREP. on, over, towards (figurative) Customs officers swooped on several houses last night looking for drugs."]},"media":{"uk":"media/ldoce/hwd/bre/7/swoop_las3_br.mp3","us":"media/ldoce/hwd/ame/7/swoop1.mp3"},"examples":[{"en":"Large quantities of drugs were found during a police swoop on the star's New York home.","cn":"警方对这个明星在纽约的住所进行突击搜查，发现了大量毒品。"},{"en":"The aircraft swooped down over the buildings.","cn":"飞机俯冲到那些建筑物上方。"}],"oxford":{"phon":"swuːp","pos":"verb","senses":[{"en":"to fly quickly and suddenly downwards, especially in order to attack somebody/something","cn":"（尤指为了袭击）向下猛冲，俯冲","g":"[intransitive]","ex":{"en":"The aircraft swooped down over the buildings.","cn":"飞机俯冲到那些建筑物上方。"}},{"en":"to visit or attack somebody/something suddenly and without warning","cn":"突然袭击；突击搜查；突然行动","g":"[intransitive]","ex":{"en":"Officers swooped on the vehicles as they left the ferry.","cn":"当车辆离开渡轮时，警察突然袭击了他们。"}},{"en":"an act of moving suddenly and quickly downwards through the air, as a bird does","cn":"（鸟等的）向下猛冲，俯冲","pos":"noun"},{"en":"an act of arriving somewhere or attacking something/somebody in a way that is sudden and unexpected","cn":"突然袭击；突击搜查；突然行动","ex":{"en":"Large quantities of drugs were found during a police swoop on the star's New York home.","cn":"警方对这个明星在纽约的住所进行突击搜查，发现了大量毒品。"},"pos":"noun"}]}},"sweeper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(足球中的)自由中卫","en":"In football, a sweeper is a player whose position is behind the main defenders but in front of the goalkeeper."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that sweeps","cn":"清扫者﹐清洁工﹔清扫机"},{"en":"a football player who plays in a position behind other defending players 〔","cn":"足球运动中的〕自由人，清道夫，拖后中卫"}]},"media":{"uk":"media/ldoce/hwd/bre/5/sweeper0205.mp3","us":"media/ldoce/hwd/ame/1/sweeper.mp3"},"examples":[{"en":"a road sweeper","cn":"马路清洁工"},{"en":"a carpet sweeper","cn":"地毯清洁器"}],"oxford":{"phon":"ˈswiːpə(r)","pos":"noun","senses":[{"en":"a person whose job is to sweep something","cn":"打扫者；清扫者；清洁工","ex":{"en":"a road sweeper","cn":"马路清洁工"}},{"en":"a thing that sweeps something","cn":"清扫器；清洁器","ex":{"en":"a carpet sweeper","cn":"地毯清洁器"}},{"en":"a player who plays behind the other defending players in order to try and stop anyone who passes them","cn":"自由中卫；清道夫"}]}},"swain":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"情郎","en":"A swain is a young man who is in love."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young man from the country who loves a woman","cn":"乡村情郎"}]},"vocab":{"pos":"n","senses":[{"en":"If you want to sound old-fashioned and a little bit fancy, you can refer to your boyfriend as your swain ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41swain.mp3","us":"media/ldoce/hwd/ame/f/swain.mp3"},"oxford":{"phon":"sweɪn","pos":"noun","senses":[{"en":"a young man who is in love","cn":"情郎"}]}},"swine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"讨厌鬼;猪猡;下流坯","en":"If you call someone a swine, you dislike them or think that they are a bad person, usually because they have behaved unpleasantly towards you."},{"pos":"N-COUNT 可数名词","cn":"猪","en":"A swine is a pig. to cast pearls before swine→see: ;","ex":{"en":"...imports of live swine from Canada.","cn":"从加拿大进口的活猪"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who behaves very rudely or unpleasantly","cn":"下流坯﹐猪猡"},{"en":"a pig","cn":"猪"}]},"vocab":{"pos":"n","senses":[{"en":"A swine is a pig or a big ol’ nasty hog. Swine have short legs, thick bodies, and they eat just about anything. If someone acts like a pig, call him a swine ."}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdeswine.mp3","us":"media/ldoce/hwd/ame/7/swine.mp3"},"examples":[{"en":"He's an arrogant little swine!","cn":"他是个傲慢的小讨厌鬼！"},{"en":"The car can be a swine to start.","cn":"这辆车有时很难发动。"}],"oxford":{"phon":"swaɪn","pos":"noun","senses":[{"en":"an unpleasant person","cn":"讨厌鬼；卑鄙小人","g":"[countable]","lab":"informal","ex":{"en":"He's an arrogant little swine!","cn":"他是个傲慢的小讨厌鬼！"}},{"en":"a difficult or unpleasant thing or task","cn":"挠头的事；烦人的事；苦差","g":"[countable]","lab":"British English, informal，，","ex":{"en":"The car can be a swine to start.","cn":"这辆车有时很难发动。"}},{"en":"pigs","cn":"猪","g":"[plural]","lab":"old use or specialist","ex":{"en":"a herd of swine","cn":"一群猪"}}]}},"sway":{"collins":{"senses":[{"pos":"VERB 动词","cn":"摇晃;摇摆;摆动","en":"When people or things sway, they lean or swing slowly from one side to the other.","ex":{"en":"The people swayed back and forth with arms linked","cn":"人们手挽手，前后摇晃着。"}},{"pos":"VERB 动词","cn":"影响;左右","en":"If you are swayed by someone or something, you are influenced by them.","ex":{"en":"Don't ever be swayed by fashion.","cn":"永远不要受潮流的影响。"}},{"pos":"PHRASE 短语","cn":"占统治地位;具有重大影响力","en":"If someone or something holds sway, they have great power or influence over a particular place or activity.","ex":{"en":"South of the Usk, a completely different approach seems to hold sway","cn":"阿斯克以南盛行的似乎是一种完全不同的方式。"}},{"pos":"PHRASE 短语","cn":"在…的控制下;在…的支配下;在…的影响下","en":"If you are under the sway of someone or something, they have great influence over you.","ex":{"en":"How mothers keep daughters under their sway is the subject of the next five sections.","cn":"在接下来的 5 节将探讨母亲怎样管教女儿。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go to a different place, or change the position of your body","cn":""},{"en":"to move slowly from one side to the other","cn":""},{"en":"to move repeatedly from one side to another, with small gentle movements","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Back and forth...back and forth...back and forth...are you sea-sick yet? The sway , or rocking motion, of a boat is too much for many stomachs."}]},"collocations":{"phrases":["ADV. gently, lightly, a little, slightly | alarmingly, dangerously, precariously The stage swayed alarmingly under their weight. | dizzily, ","VERB + SWAY begin to","PREP. in The curtains swayed gently in the breeze. 2 influence sb/sth","ADV. easily He will not easily be swayed by argument."]},"media":{"uk":"media/ldoce/hwd/bre/0/sway_v0205.mp3","us":"media/ldoce/hwd/ame/a/sway1.mp3"},"examples":[{"en":"She wasn't swayed by his good looks or his clever talk.","cn":"他相貌不凡，谈吐风趣，但她不为其所动。"},{"en":"They danced rhythmically, swaying their hips to the music.","cn":"他们伴着音乐扭动屁股，有节奏地跳舞。"}],"oxford":{"phon":"sweɪ","pos":"verb","senses":[{"en":"to move slowly from side to side; to move something in this way","cn":"（使）摇摆，摇动","g":"[intransitive, transitive]","ex":{"en":"The branches were swaying in the wind.","cn":"树枝在风中摇曳。"}},{"en":"to persuade somebody to believe something or do something","cn":"说服；使相信；使动摇","g":"[transitive, often passive]","ex":{"en":"He's easily swayed.","cn":"他很容易动摇。"}},{"en":"movement from side to side","cn":"摇摆；摆动","ex":{"en":"The sway of the yacht was making her feel sick.","cn":"游艇的摇晃让她感到恶心。"},"pos":"noun"},{"en":"power or influence over somebody","cn":"统治；势力；支配；控制；影响","lab":"literary","ex":{"en":"Rebel forces hold sway over much of the island.","cn":"该岛很大一部分控制在叛军手里。"},"pos":"noun"}]}},"swarthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"皮肤黝黑的;深肤色的","en":"A swarthy person has a dark face.","ex":{"en":"He had a broad swarthy face.","cn":"他有一张黝黑的大脸。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is swarthy has dark skin 〔","cn":"人〕肤色黝黑的"}]},"vocab":{"pos":"adj","senses":[{"en":"Swarthy means dark skinned. If you like tall, dark and handsome men, you find a swarthy complexion attractive."}]},"media":{"uk":"media/ldoce/hwd/bre/5/swarthy0205.mp3","us":"media/ldoce/hwd/ame/8/swarthy.mp3"},"examples":[{"en":"a small, swarthy man","cn":"一个个子矮小﹑皮肤黝黑的男人"},{"en":"a swarthy complexion","cn":"黝黑的肤色"}],"oxford":{"phon":"ˈswɔːði","pos":"adjective","senses":[{"en":"having dark skin","cn":"肤色深的；皮肤黝黑的","ex":{"en":"a swarthy complexion","cn":"黝黑的肤色"}}]}},"sweaty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"满是汗的;汗淋淋的","en":"If parts of your body or your clothes are sweaty, they are soaked or covered with sweat.","ex":{"en":"...sweaty hands","cn":"汗津津的手"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热得(或累得)让人出汗的","en":"A sweaty place or activity makes you sweat because it is hot or tiring.","ex":{"en":"...a sweaty nightclub.","cn":"热得让人冒汗的夜总会"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be very wet because you have been sweating a lot","cn":""},{"en":"covered or wet with sweat","cn":"满是汗的﹔被汗水湿透的"},{"en":"unpleasantly hot or difficult, so that you sweat","cn":"闷热得[困难得]使人出汗的"}]},"collocations":{"phrases":["VERBS be, feel, look, smell | become, get","ADV. really, very | all Ugh! You're all sweaty and horrible! | a bit, rather","PREP. from Her forehead was sweaty from the pain she was in. | with feeling sweaty with embarrassment"]},"media":{"uk":"media/ldoce/hwd/bre/f/sweaty0205.mp3","us":"media/ldoce/hwd/ame/d/sweaty.mp3"},"examples":[{"en":"It was sweaty work, under the hot sun.","cn":"在火辣辣的太阳下干这活儿，让人汗流浃背。"},{"en":"He felt all hot and sweaty.","cn":"他感觉全身发热，满身是汗。"}],"oxford":{"phon":"ˈsweti","pos":"adjective","senses":[{"en":"covered or wet with sweat","cn":"满是汗的；汗津津的；汗水湿透的","ex":{"en":"sweaty feet","cn":"汗湿的脚"}},{"en":"making you become hot and covered with sweat","cn":"热得让人出汗的","g":"[only before noun]","ex":{"en":"It was sweaty work, under the hot sun.","cn":"在火辣辣的太阳下干这活儿，让人汗流浃背。"}}]}},"swedish":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"瑞典的;瑞典人的;瑞典语的;瑞典文化的","en":"Swedish means belonging or relating to Sweden, or to its people, language, or culture.","ex":{"en":"Half of Swedish marriages end in divorce.","cn":"瑞典人的婚姻有一半以离婚告终。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"瑞典语","en":"Swedish is the language spoken in Sweden.","ex":{"en":"I had a chat with Lars in the morning and spoke Swedish.","cn":"上午，我用瑞典话和拉尔斯聊了一会。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to Sweden, its people, or its language","cn":"瑞典的﹔瑞典人的﹔瑞典语的"},{"en":"people from Sweden","cn":"瑞典人"},{"en":"the language used in Sweden","cn":"瑞典语"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41swedish.mp3","us":"media/ldoce/hwd/ame/5/ld41swedish.mp3"},"oxford":{"phon":"ˈswiːdɪʃ","pos":"adjective","senses":[{"en":"from or connected with Sweden","cn":"瑞典的"}]}},"swish":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)刷地(或嗖地、呼地)快速移动","en":"If something swishes or if you swish it, it moves quickly through the air, making a soft sound.","ex":{"en":"A car swished by heading for the coast","cn":"一辆车嗖地驶过朝海岸开去。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好看的;时髦的;高档的","en":"If you describe something as swish, you mean that it is smart and fashionable.","ex":{"en":"...a swish cocktail bar.","cn":"时髦的鸡尾酒酒吧"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the continuous, low, quiet sound of something that is a fairly long way away or that is continuously there as well as other noises","cn":""},{"en":"if things such as papers, leaves, or clothes rustle , they make a continuous quiet sound as they rub against each other","cn":""},{"en":"the smooth quiet sound produced when something such as a skirt or curtains moves quickly through the air","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/swish_v0205.mp3","us":"media/ldoce/hwd/ame/d/swish1.mp3"},"examples":[{"en":"A large car swished past them and turned into the embassy gates.","cn":"一辆大型轿车嗖地从他们身边驶过，拐进了大使馆的大门。"},{"en":"She swished her racket aggressively through the air.","cn":"她咄咄逼人地把球拍挥舞得呼呼作响。"}],"oxford":{"phon":"swɪʃ","pos":"verb","senses":[{"en":"to move quickly through the air in a way that makes a soft sound; to make something do this","cn":"唰地（或嗖地、呼地等）挥动；（使）快速空中移动","ex":{"en":"A large car swished past them and turned into the embassy gates.","cn":"一辆大型轿车嗖地从他们身边驶过，拐进了大使馆的大门。"}},{"en":"the movement or soft sound made by something moving quickly, especially through the air","cn":"快速的空中移动（或挥动、摆动等）；（快速空中挥动等的）唰唰声，嗖嗖声，呼呼声","ex":{"en":"She turned away with a swish of her skirt.","cn":"她转身离开，裙子发出窸窣的响声。"},"pos":"noun"},{"en":"looking expensive and fashionable","cn":"华贵入时的；豪华的","ex":{"en":"a swish restaurant","cn":"豪华餐馆"},"pos":"adjective"}]}},"swivel":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)旋转;(使)转动","en":"If something swivels or if you swivel it, it turns around a central point so that it is facing in a different direction.","ex":{"en":"She swivelled her chair round and stared out across the back lawn","cn":"她把椅子转过来，向外凝视着屋后的草坪。"}},{"pos":"VERB 动词","cn":"(突然)转身朝向","en":"If you swivel in a particular direction, you turn suddenly in that direction.","ex":{"en":"He swivelled round to face Sarah.","cn":"他转过身面对着萨拉。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(头或眼睛)转动","en":"If your head or your eyes swivel in a particular direction or if you swivel them in a particular direction, you quickly look in that direction.","ex":{"en":"Roger swivelled his head to look at her","cn":"罗杰转过头看着她。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something turn by moving it with your hand","cn":""},{"en":"to turn something with a quick firm circular movement","cn":""},{"en":"to turn something such as a handle or part of a machine around and around, especially in order to make something move or start working","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A swivel is a device that allows something to turn freely. Desk chairs are often designed so the seat can swivel atop the base. In the hospital, the TV is usually mounted on a swivel so that the nurses can adjust its facing."}]},"media":{"uk":"media/ldoce/hwd/bre/c/swivel_v0205.mp3","us":"media/ldoce/hwd/ame/9/swivel1.mp3"},"examples":[{"en":"She swivelled the chair around to face them.","cn":"她把椅子转过来朝着他们。"},{"en":"He swivelled around to look at her.","cn":"他转过身来看着她。"}],"oxford":{"phon":"ˈswɪvl","pos":"noun","senses":[{"en":"a device used to connect two parts of an object together, allowing one part to turn around without moving the other","cn":"转节；转环；旋轴；旋转接头","ex":{"en":"a swivel chair (= one on which the seat turns around without moving the base)","cn":"转椅"}},{"en":"to turn or make something turn around a fixed central point","cn":"（使）旋转，转动","g":"[transitive, intransitive]","ex":{"en":"She swivelled the chair around to face them.","cn":"她把椅子转过来朝着他们。"},"pos":"verb"},{"en":"to turn or move your body, eyes or head around quickly to face another direction","cn":"转身；转动（身体、眼睛或头）","g":"[intransitive, transitive]","ex":{"en":"He swivelled around to look at her.","cn":"他转过身来看着她。"},"pos":"verb"}]}},"swill":{"collins":{"senses":[{"pos":"VERB 动词","cn":"大口喝;狂饮","en":"If you swill an alcoholic drink, you drink a lot of it.","ex":{"en":"A crowd of men were standing around swilling beer.","cn":"一群人正站在一起痛饮啤酒。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(液体)晃动,摇晃;(使)来回流动","en":"If a liquid swills around, or if you swill it around, it moves around the area that it is contained in.","ex":{"en":"Gallons of sea water had rushed into the cabin and were now swilling about in the bilges","cn":"大量海水冲入了船舱，正在船底来回晃荡。"}},{"pos":"VERB 动词","cn":"冲刷;冲洗;涮","en":"To swill out something means to clean it by pouring water over it.","ex":{"en":"Having finished his coffee, he swilled out the mug and left it on the draining board.","cn":"喝完咖啡后，他涮了涮杯子然后把它放在滴水板上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"泔脚饲料;猪食","en":"Swill is a liquid mixture containing waste food that is given to pigs to eat."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to wash something by pouring a lot of water over it or into it 〔","cn":"用水〕冲洗﹐涮"},{"en":"if a liquid swills around or you swill it around, it moves around something （","cn":"使）〔液体〕摇动[晃动]"},{"en":"to drink something in large amounts","cn":"大口喝﹔痛饮"}]},"media":{"uk":"media/ldoce/hwd/bre/1/swill_n0205.mp3","us":"media/ldoce/hwd/ame/7/swill1.mp3"},"examples":[{"en":"He had a quick swill of wine.","cn":"他猛地灌下一大口葡萄酒。"},{"en":"He swilled the juice around in his glass.","cn":"他摇了摇杯子里的果汁。"}],"oxford":{"phon":"swɪl","pos":"verb","senses":[{"en":"to clean something by pouring large amounts of water in, on or through it","cn":"冲洗；灌洗；涮","g":"[transitive]","lab":"especially British English","ex":{"en":"She swilled the glasses with clean water.","cn":"她用清水涮了杯子。"}},{"en":"to drink something quickly and/or in large quantities","cn":"大口喝；痛饮","g":"[transitive]","lab":"informal"},{"en":"to move, or to make a liquid move, in a particular direction or around a particular place","cn":"（使）晃荡，摇动，流动","g":"[transitive, intransitive]","ex":{"en":"He swilled the juice around in his glass.","cn":"他摇了摇杯子里的果汁。"}},{"en":"a mixture of waste food and water that is given to pigs to eat","cn":"（给猪吃的）泔脚，剩饭菜，馊水","g":"[uncountable]","pos":"noun"},{"en":"drink or food that is unpleasant or of a poor quality","cn":"不好喝的饮料；难吃的食物；劣质饮料（或食物）","g":"[uncountable]","lab":"informal","pos":"noun"},{"en":"a large amount of a drink that you take into your mouth","cn":"一大口饮料","g":"[countable, usually singular]","lab":"informal","ex":{"en":"He had a quick swill of wine.","cn":"他猛地灌下一大口葡萄酒。"},"pos":"noun"}]}},"sweetbread":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(从小牛或羔羊身上割下供食用的)胰脏","en":"Sweetbreads are meat obtained from the pancreas of a calf or a lamb."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"meat from the pancreas of a young sheep or cow 〔","cn":"从小羊或小牛身上取下供食用的〕胰脏"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41sweetbread.mp3","us":"media/ldoce/hwd/ame/6/sweetbread.mp3"},"oxford":{"phon":"ˈswiːtbred","pos":"noun","senses":[{"en":"the thymus (= an organ in the neck) or the pancreas (= an organ near the stomach) of a young cow or sheep, eaten as food","cn":"（食用的小牛或羊的）胸腺，胰脏"}]}},"swagger":{"collins":{"senses":[{"pos":"VERB 动词","cn":"趾高气扬地走;大摇大摆地走","en":"If you swagger, you walk in a very proud, confident way, holding your body upright and swinging your hips.","ex":{"en":"A broad shouldered man wearing a dinner jacket swaggered confidently up to the bar","cn":"穿晚礼服的宽肩膀男子神气十足地走向吧台。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk proudly, swinging your shoulders, in a way that shows too much self-confidence","cn":""},{"en":"to walk proudly with your head high, shoulders back, and chest pushed forwards in a way that shows you think you are important or impressive","cn":""},{"en":"to walk proudly around a place, in a way that shows you want people to notice and admire you","cn":""}]},"vocab":{"pos":"v n adj","senses":[{"en":"Picture the confident, maybe even arrogant way a pirate, a cowboy, or even a rapper might stroll around. That style of walking is called a swagger ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeswagger.mp3","us":"media/ldoce/hwd/ame/e/swagger1.mp3"},"examples":[{"en":"He swaggered over towards me.","cn":"他趾高气扬地向我走来。"},{"en":"He walked in with a swagger.","cn":"他趾高气扬地走了进来。"}],"oxford":{"phon":"ˈswæɡə(r)","pos":"verb","senses":[{"en":"to walk in an extremely proud and confident way","cn":"神气十足地走；大摇大摆地走","ex":{"en":"He swaggered into the room looking very pleased with himself.","cn":"他大摇大摆地走进房间，看上去很得意。"}},{"en":"a way of walking or behaving that seems too confident","cn":"神气十足；大摇大摆","ex":{"en":"She walked to the front of the class with a swagger.","cn":"她大摇大摆地走到班级前面。"},"pos":"noun"}]}},"switchblade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(按钮式)弹簧小折刀","en":"A switchblade is a knife with a blade that is hidden in the handle and that springs out when a button is pressed."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a knife with a blade inside the handle which springs out when you press a button","cn":"弹簧（小折）刀"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41switchblade.mp3","us":"media/ldoce/hwd/ame/1/switchblade.mp3"},"oxford":{"phon":"ˈswɪtʃbleɪd","pos":"noun","senses":[{"en":"a knife with a blade (= sharp metal cutting part) inside the handle that jumps out quickly when a button is pressed","cn":"弹簧刀","ex":{"en":"Owning or carrying a switchblade is illegal in the United Kingdom.","cn":"在英国，持有或携带弹簧刀是违法的。"}}]}},"swaddle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(用布)包裹，裹紧(婴儿)","en":"If you swaddle a baby, you wrap cloth around it in order to keep it warm or to prevent it from moving.","ex":{"en":"Swaddle your newborn baby so that she feels secure.","cn":"把你刚出生的孩子用襁褓包裹住，这样她会有安全感。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to wrap a baby tightly to keep it warm and protect it","cn":"用襁褓包裹〔婴孩〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you swaddle a baby, you wrap her in a blanket. Parents often swaddle a crying newborn to soothe and comfort her."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41swaddle.mp3","us":"media/ldoce/hwd/ame/5/swaddle.mp3"},"oxford":{"phon":"ˈswɒdl","pos":"verb","senses":[{"en":"to wrap somebody/something, especially a baby, tightly in clothes or a piece of cloth","cn":"（用衣服或布）紧裹，包裹（尤指婴儿）"}]}},"swoon":{"collins":{"senses":[{"pos":"VERB 动词","cn":"痴迷;对…神魂颠倒","en":"If you swoon, you are strongly affected by your feelings for someone you love or admire very much.","ex":{"en":"Virtually every woman in the '20s swooned over Valentino","cn":"在 20 年代，几乎每位女性都痴迷于华伦天奴这个品牌。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be extremely excited and unable to control yourself because you admire someone so much 〔","cn":"对某人〕神魂颠倒"},{"en":"to fall to the ground because you have been affected by an emotion or shock","cn":"晕倒﹐昏倒"}]},"vocab":{"pos":"v n","senses":[{"en":"To swoon is to faint, due to lack of blood to the brain. Illness, fear, stress, and even happiness can cause people to swoon ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41swoon.mp3","us":"media/ldoce/hwd/ame/6/swoon1.mp3"},"examples":[{"en":"He's used to having women swooning over him.","cn":"他对有女人痴迷于他司空见惯了。"},{"en":"( old-fashioned ) to go into a swoon","cn":"昏厥"}],"oxford":{"phon":"swuːn","pos":"verb","senses":[{"en":"to feel very excited, emotional, etc. about somebody that you think is sexually attractive","cn":"痴迷；对（某人）神魂颠倒","g":"[intransitive]","ex":{"en":"He's used to having women swooning over him.","cn":"他对有女人痴迷于他司空见惯了。"}},{"en":"to become unconscious","cn":"昏迷；昏倒","g":"[intransitive]","lab":"old-fashioned"},{"en":"the state of being unconscious","cn":"无知觉；不省人事","ex":{"en":"to go into a swoon","cn":"昏厥"},"pos":"noun"}]}},"sweeten":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使变甜;加糖于","en":"If you sweeten food or drink, you add sugar, honey, or another sweet substance to it.","ex":{"en":"He liberally sweetened his coffee","cn":"他往咖啡里加了很多糖。"}},{"pos":"VERB 动词","cn":"改善;使更合心意;使更有诱惑力","en":"If you sweeten something such as an offer or a business deal, you try to make someone want it more by improving it or by increasing the amount you are willing to pay.","ex":{"en":"Kalon Group has sweetened its takeover offer for Manders","cn":"卡龙集团已经向曼德斯公司开出更为优厚的收购条件。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"food or drink that is sweet has a taste like sugar","cn":""},{"en":"very sweet or too sweet because a lot of sugar has been added","cn":""},{"en":"tasting unpleasantly sweet","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/sweeten0205.mp3","us":"media/ldoce/hwd/ame/4/sweeten.mp3"},"examples":[{"en":"Sweeten the mixture with a little honey.","cn":"往混合料里加点蜂蜜。"},{"en":"a cash bonus to sweeten the deal","cn":"疏通交易的奖励金"}],"oxford":{"phon":"ˈswiːtn","pos":"verb","senses":[{"en":"to make food or drinks taste sweeter by adding sugar, etc.","cn":"使变甜；加糖于","ex":{"en":"Milky tea sweetened with honey is my four o'clock treat.","cn":"加蜂蜜的奶茶是我四点钟的享受。"}},{"en":"to try to make somebody more willing to help you, agree to something, etc. by giving them money, praising them, etc.","cn":"讨好；拉拢；哄；收买；恭维","lab":"informal","ex":{"en":"You're always trying to sweeten her up.","cn":"你总是试图让她变得甜蜜。"}},{"en":"to make something more pleasant or acceptable","cn":"使令人愉快；使更合心意；改善；缓和","ex":{"en":"The fall in inflation did little to sweeten news of massive job losses.","cn":"通货膨胀的下降并没有让大规模失业的消息好起来。"}}]}},"sweetly":{"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"(引擎或机器运转)正常地,良好地","en":"If an engine or machine is running sweetly, it is working smoothly and efficiently.","ex":{"en":"He heard the car engine running sweetly beyond the open door.","cn":"他听到敞开的门口外的汽车引擎运转正常。"}},{"pos":"ADV-GRADED 副词","cn":"(踢球、击球)正中地,精准地","en":"If you kick or hit a ball sweetly, you kick or hit it in the very middle of it so that it goes firmly and accurately to the place you are aiming for.","ex":{"en":"He could strike the ball as sweetly as when he was 28 years younger.","cn":"他击球可以和 28 年前一样准。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"sweet food or drink has had sugar added or contains natural sugars","cn":""},{"en":"sweet because a lot of sugar has been added","cn":""},{"en":"tasting unpleasantly sweet","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdesweet.mp3","us":"media/ldoce/hwd/ame/0/suite.mp3"},"examples":[{"en":"He headed the ball sweetly into the back of the net.","cn":"他把球稳稳地顶入网窝。"},{"en":"Everything went sweetly and according to plan.","cn":"一切按计划顺利进行。"}],"oxford":{"phon":"ˈswiːtli","pos":"adverb","senses":[{"en":"in a pleasant way","cn":"令人愉快地；可爱地","ex":{"en":"She smiled sweetly at him.","cn":"她朝他嫣然一笑。"}},{"en":"in a way that smells sweet","cn":"气味芬芳地","ex":{"en":"a sweetly scented flower","cn":"气味芬芳的花"}},{"en":"in a way that is without difficulties or problems","cn":"顺利地；顺顺当当地","ex":{"en":"Everything went sweetly and according to plan.","cn":"一切按计划顺利进行。"}}]}},"swelter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"热得难受;热得发昏","en":"If you swelter, you are very uncomfortable because the weather is extremely hot.","ex":{"en":"They sweltered in temperatures rising to a hundred degrees","cn":"接近华氏 100 度的高温让他们感觉酷热难耐。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feel extremely hot and uncomfortable","cn":"热得难受"}]},"vocab":{"pos":"v","senses":[{"en":"To swelter is to be hot — very, very hot, like on a humid, ninety-degree day. To swelter is to feel like you're in an oven."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41swelter.mp3","us":"media/ldoce/hwd/ame/f/swelter.mp3"},"examples":[{"en":"Passengers sweltered in temperatures of over 90°F.","cn":"在超过 90 华氏度的高温下，乘客热得要命。"},{"en":"sweltering heat","cn":"酷热难耐的高温"}],"oxford":{"phon":"ˈsweltə(r)","pos":"verb","senses":[{"en":"to be very hot in a way that makes you feel uncomfortable","cn":"热得难受","ex":{"en":"Passengers sweltered in temperatures of over 90°F.","cn":"在超过 90 华氏度的高温下，乘客热得要命。"}}]}},"swathe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(土地的)一长条，一长片","en":"A swathe of land is a long strip of land.","ex":{"en":"On May 1st the army took over another swathe of territory","cn":"军队在5月1号又接管了另一长条领土。"}},{"pos":"N-COUNT 可数名词","cn":"一长条(尤指用来包裹某人或某物的布料)","en":"A swathe of cloth is a long strip of cloth, especially one that is wrapped around someone or something.","ex":{"en":"...swathes of white silk.","cn":"几条白丝缎"}},{"pos":"VERB 动词","cn":"(用布料)把…包裹住，把…围住","en":"To swathe someone or something in cloth means to wrap them in it completely.","ex":{"en":"She swathed her enormous body in thin black fabrics","cn":"她用薄薄的黑色织物裹住了自己硕大的身躯。"}},{"pos":"PHRASE 短语","cn":"使遭到严重破坏;使发生巨变","en":"If a person or thing cuts a swathe through something, they pass through it causing great destruction or change.","ex":{"en":"The storm cut a swathe through southern England","cn":"风暴重创了英格兰南部。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin area of something, especially land","cn":"一长条〔尤指土地〕"},{"en":"a long thin area of grass or plants that has been cut down 〔","cn":"割下草或植物后的〕一长条田地"},{"en":"to destroy a large amount or part of something","cn":"把某物夷为平地﹔严重损毁某物"}]},"vocab":{"pos":"v n","senses":[{"en":"When you swathe yourself in a blanket, you are wrapping or swaddling yourself up in it. Swathe a baby up and you're creating a little cocoon where she can sleep."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41swathe.mp3","us":"media/ldoce/hwd/ame/0/swathe.mp3"},"examples":[{"en":"The combine had cut a swathe around the edge of the field.","cn":"联合收割机把庄稼绕田边割了一长条。"},{"en":"He was lying on the hospital bed, swathed in bandages.","cn":"他裹着绷带，躺在医院的病床上。"}],"oxford":{"phon":"sweɪð","pos":"noun","senses":[{"en":"a long piece of land, especially one on which the plants or crops have been cut","cn":"（尤指割去植物或庄稼后的）一长条田地","ex":{"en":"The combine had cut a swathe around the edge of the field.","cn":"联合收割机把庄稼绕田边割了一长条。"}},{"en":"a large piece or area of something","cn":"一长条；一长片","ex":{"en":"The mountains rose above a swathe of thick cloud.","cn":"群峰耸立在云海之上。"}},{"en":"to wrap or cover somebody/something in something","cn":"包；裹；覆盖","ex":{"en":"He was lying on the hospital bed, swathed in bandages.","cn":"他裹着绷带，躺在医院的病床上。"},"pos":"verb"}]}},"swimmer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"游泳运动员;游泳爱好者;游泳者","en":"A swimmer is a person who swims, especially for sport or pleasure, or a person who is swimming.","ex":{"en":"You don't have to worry about me. I'm a good swimmer","cn":"你不用担心我。我水性很好。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who swims well, often as a competitor","cn":"会游泳的人﹔游泳运动员"},{"en":"someone who is swimming","cn":"正在游泳的人"}]},"collocations":{"phrases":["ADJ. good, keen, strong She's a strong swimmer. | poor | champion, competitive, Olympic"]},"media":{"uk":"media/ldoce/hwd/bre/0/swimmer0205.mp3","us":"media/ldoce/hwd/ame/0/laadswimmer.mp3"},"examples":[{"en":"They watched the swimmers splashing through the water.","cn":"他们看着游泳的人扑通扑通溅着水花游过去。"},{"en":"a good/strong swimmer","cn":"水性好的人；擅长游泳的人"}],"oxford":{"phon":"ˈswɪmə(r)","pos":"noun","senses":[{"en":"a person who can swim; a person who is swimming","cn":"会游泳者；游泳者","ex":{"en":"a good/strong swimmer","cn":"水性好的人；擅长游泳的人"}}]}},"swahili":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Bantu language spoken in eastern and central Africa, and used especially as a lingua franca (= a language used between people whose first languages are different ) . It is the official language of Kenya and Tanzania.","cn":""},{"en":"a member of the Bantu people of Zanzibar who originally spoke this language","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/lpd_swahili.mp3","us":"media/ldoce/hwd/ame/8/swahili_n.mp3"},"oxford":{"phon":"swəˈhiːli","pos":"noun","senses":[{"en":"a language widely used in East Africa, especially between people who speak different first languages","cn":"斯瓦希里语（在东非广泛使用，尤用于母语不同者之间的交流）"}]}},"swiss":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"瑞士的;瑞士人的;瑞士文化的","en":"Swiss means belonging or relating to Switzerland, or to its people or culture.","ex":{"en":"...an avalanche in the Swiss alps.","cn":"瑞士阿尔卑斯山脉的一次雪崩"}},{"pos":"N-COUNT 可数名词","cn":"瑞士人","en":"The Swiss are the people of Switzerland.","ex":{"en":"The report shows the Swiss are among the world's top wage earners.","cn":"报告显示瑞士人的工资收入位列世界最高水平。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a country in western Europe with many mountains and lakes, surrounded by France, Germany, Austria, and Italy. Population: 7,996,026 (2014). Capital: Bern. Switzerland is known for being a neutral country (= one that does not support any side in a war ) . It re","cn":""},{"en":"relating to Switzerland or its people","cn":"瑞士的﹔瑞士人的"},{"en":"people from Switzerland","cn":"瑞士人"}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000011797.mp3","us":"media/ldoce/hwd/ame/d/p028-000011797.mp3"},"oxford":{"phon":"swɪs","pos":"adjective","senses":[{"en":"from or connected with Switzerland","cn":"瑞士的"},{"en":"a person from Switzerland","cn":"瑞士人","pos":"noun"}]}},"swot":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指为准备考试)刻苦学习，用功","en":"If you swot, you study very hard, especially when you are preparing for an examination.","ex":{"en":"They swotted for their A levels.","cn":"他们为准备高级程度考试而刻苦学习。"}},{"pos":"N-COUNT 可数名词","cn":"只知一味用功学习的人;书呆子","en":"If you call someone a swot, you disapprove of the fact that they study extremely hard and are not interested in other things."},{"pos":"","cn":"","en":"相关词组：swot up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who wants to work all the time and who cannot relax when they are not working","cn":""},{"en":"someone who is industrious works hard and effectively","cn":""},{"en":"someone who is dedicated works very hard at something because they care about it a lot, even though the job is difficult or does not earn them much money","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/swot0205.mp3","us":"media/ldoce/hwd/ame/6/ld42swot.mp3"},"examples":[{"en":"Make sure you swot up on the company before the interview.","cn":"面试前一定要用心掌握公司的情况。"},{"en":"a SWOT analysis","cn":"强弱机危综合分析法"}],"oxford":{"phon":"swɒt","pos":"noun","senses":[{"en":"a person who spends too much time studying","cn":"只知一味用功学习的人；书呆子"},{"en":"to study very hard, especially in order to prepare for an exam","cn":"（尤指为准备考试）刻苦学习，用功","pos":"verb"}]}},"swede":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瑞典人;瑞典裔人","en":"A Swede is a Swedish citizen, or a person of Swedish origin."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round yellow vegetable that grows under the ground","cn":"芜菁甘蓝﹐瑞典芜菁"}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeswede.mp3","us":"media/ldoce/hwd/ame/6/ld41swede2.mp3","img":["media/thumb/swede.jpg"]},"oxford":{"phon":"swiːd","pos":"noun","senses":[{"en":"a large round yellow root vegetable","cn":"芜菁甘蓝；大头菜"},{"en":"a person from Sweden","cn":"瑞典人"}]}},"swag":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"盗窃物;赃款;赃物","en":"Swag is stolen goods, or money obtained illegally."},{"pos":"N-COUNT 可数名词","cn":"(挂在窗户上的)窗饰","en":"A swag is a piece of material that is put above a window and hangs down in a decorative way."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"goods that someone has stolen","cn":"赃物﹔被盗货物"},{"en":"a large piece of material that is hung above a window as decoration 〔","cn":"窗户上方的〕垂挂装饰物"},{"en":"a rope covered with flowers or fruit that is hung somewhere as decoration, or carve d or painted on something","cn":"垂花饰"}]},"vocab":{"pos":"n v","senses":[{"en":"Swag refers to valuable goods, often obtained illegally. Just because your friend has a bag of swag does not make him a pirate (although the patch and wooden leg might say otherwise)."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41swag.mp3","us":"media/ldoce/hwd/ame/b/swag.mp3"},"oxford":{"phon":"swæɡ","pos":"noun","senses":[{"en":"goods that have been stolen","cn":"被盗货品；赃物","g":"[uncountable]","lab":"old-fashioned, informal，，"},{"en":"products given away free, especially at a marketing event","cn":"（尤指促销活动的）赠品","g":"[uncountable]","lab":"informal","ex":{"en":"Everyone who attends gets a swag bag and a T-shirt.","cn":"出席者会得到一个礼品包和一件 T 恤。"}},{"en":"cloth that is hung in large curved folds as decoration, especially above a window","cn":"（挂于窗户等上方的）装饰性布幔（或帷幕）","g":"[countable, usually plural]"},{"en":"a pack of things tied or wrapped together and carried by a traveller","cn":"（旅行者携带的）包裹；行囊","g":"[countable]","lab":"Australian English, New Zealand English，，"},{"en":"a large number, amount or variety of something","cn":"大量；多种","g":"[countable]","lab":"Australian English, New Zealand English, informal，，，，","ex":{"en":"The novel has won a swag of awards.","cn":"这部小说得奖无数。"}},{"en":"a bunch of flowers or fruit that is carved onto walls, etc. as decoration","cn":"垂花饰（雕刻装饰，形状为串起来的花、果等）","g":"[countable, usually plural]"},{"en":"a confident attitude that you admire","cn":"范儿；气场","g":"[uncountable]","lab":"informal, approving，，","ex":{"en":"This guy's got some serious swag.","cn":"这家伙真有范儿。"}}]}},"swank":{"collins":{"senses":[{"pos":"VERB 动词","cn":"炫耀;吹嘘;卖弄","en":"If someone is swanking, they are speaking about things they own or things they have achieved, in order to impress other people.","ex":{"en":"I have always been against swanking about all the things I have been lucky enough to win.","cn":"我一向不喜欢和别人炫耀自己因为幸运而取得的那些成就。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同 swanky","en":"Swank means the same as swanky .","ex":{"en":"...a swank new shop on the outskirts of Beijing.","cn":"北京郊区新开的一家高档时尚商店"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to speak or behave in a way that shows you think you are better than other people","cn":"炫耀﹐吹嘘﹐摆阔"},{"en":"proud confident behaviour that shows you think you are better than other people","cn":"炫耀﹔摆架子﹔卖弄"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41swank2.mp3","us":"media/ldoce/hwd/ame/9/ld41swank2.mp3"},"examples":[{"en":"I wish you’d stop swanking!","cn":"我希望你别再吹了！"}],"oxford":{"phon":"swæŋk","pos":"verb","senses":[{"en":"to behave in way that is too proud or confident","cn":"炫耀；卖弄"}]}},"sweetie":{"collins":{"senses":[{"pos":"N-VOC 称呼名词","cn":"(尤用作对自己小的人的爱称)亲爱的，小宝贝儿","en":"You can call someone sweetie if you are fond of them, especially if they are younger than you."},{"pos":"N-COUNT 可数名词","cn":"好心人;善人","en":"If you say that someone is a sweetie, you mean that they are kind and nice."},{"pos":"N-COUNT 可数名词","cn":"(儿童用语)糖果","en":"Sweets are sometimes referred to as sweeties by children or by adults speaking to children."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sweet – used by children or when speaking to children","cn":"糖果〔儿语〕"},{"en":"someone who is kind and easy to love","cn":"讨人喜欢的人"},{"en":"a way of speaking to someone you love","cn":"亲爱的﹐甜心〔用作爱称〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41sweetie.mp3","us":"media/ldoce/hwd/ame/0/sweetie.mp3"},"examples":[{"en":"He's a real sweetie.","cn":"他的确招人喜欢。"},{"en":"Guy’s father is such a sweetie.","cn":"盖伊的父亲非常讨人喜欢。"}],"oxford":{"phon":"ˈswiːti","pos":"noun","senses":[{"en":"a child’s word for a sweet","cn":"（儿童语）糖果","g":"[countable]","lab":"British English"},{"en":"a person who is kind and easy to like","cn":"招人喜欢的人；可爱的人","g":"[countable]","ex":{"en":"He's a real sweetie.","cn":"他的确招人喜欢。"}},{"en":"used to address somebody in a kind and loving way","cn":"（用作称呼语）亲爱的","g":"[singular]","ex":{"en":"If you ask me, sweetie, you’re making a big mistake.","cn":"亲爱的，如果你问我，我说你是大错特错了。"}}]}},"sweetener":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(人造的)甜味剂","en":"Sweetener is an artificial substance that can be used in drinks instead of sugar."},{"pos":"N-COUNT 可数名词","cn":"好处;用以拉拢人的钱物;贿赂","en":"A sweetener is something that you give or offer someone in order to persuade them to accept an offer or business deal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that encourages you to work harder, start new activities etc","cn":""},{"en":"something that is offered to someone to make a deal or plan seem more attractive, so that they will accept it","cn":""},{"en":"a reward that is offered to someone to encourage them to do something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdesweetener.mp3","us":"media/ldoce/hwd/ame/c/sweetener.mp3"},"examples":[{"en":"artificial sweetener(s)","cn":"人造甜味剂"},{"en":"No artificial sweeteners are used in this product.","cn":"本产品未使用人造甜味剂。"}],"oxford":{"phon":"ˈswiːtnə(r)","pos":"noun","senses":[{"en":"a substance used to make food or drink taste sweeter, used instead of sugar","cn":"甜味剂","g":"[uncountable, countable]","lab":"British English","ex":{"en":"artificial sweetener(s)","cn":"人造甜味剂"}},{"en":"something that is given to somebody in order to persuade them to do something, especially when this is done in a secret or dishonest way","cn":"用以拉拢人的钱物；贿赂","g":"[countable]","lab":"informal","ex":{"en":"Financial sweeteners were used to secure the deal.","cn":"为了确保这笔交易，他们使用了财务甜头。"}}]}},"sweetish":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(气味、味道)甜丝丝的，有点甜的","en":"A sweetish smell or taste is fairly sweet."}]},"oxford":{"phon":"ˈswiːtɪʃ","pos":"adjective","senses":[{"en":"fairly sweet","cn":"有点甜的；带甜味的"}]}}});
